--- ============================================================================
--- MSUF - ruRU
---
--- Basic translations for Midnight Simple Unit Frames.
--- Keys are the original English UI strings.
---
--- Perf note:
--- This file is an immediate no-op unless the active locale is ruRU.
--- ============================================================================
local MSUF = _G.MSUF_NS or _G.MSUF
if not MSUF then return end
local function LoadLocale()
local L = (MSUF.RegisterLocale and MSUF.RegisterLocale("ruRU")) or (MSUF.L or {})

-- Group layout and cast bar options.
L["Center party frames while solo"] = "Центрировать рамки группы при игре в одиночку"
L["Class priority"] = "Приоритет классов"
L["Class priority order"] = "Порядок приоритета классов"
L["Collapse empty preserved raid groups"] = "Убирать промежутки от пустых сохранённых групп рейда"
