-- Spell bar and group layout options.
L["When Hide out of combat is enabled, hide the Player Power bar and its text with Class Resource. Player Power returns in combat. Edit Mode keeps them visible."] = "Когда включено «Скрывать вне боя», скрывает полосу ресурса игрока и её текст вместе с классовым ресурсом. Ресурс игрока снова появляется в бою. В режиме редактирования полоса и текст остаются видимыми."

