local MSUF_LOCALE_COVERAGE_ruRU = {
    ["!msuf help      - Print this help via chat (from your own character)."] = "!msuf help      - вывести эту справку в чат (от вашего персонажа).",
    ["(then /reload OR MSUF Menu > Advanced > Factory Reset)"] = "(затем /reload ИЛИ MSUF Меню > Дополнительно > Сброс настроек)",
