    ["Opens: Global Style > Colors > Bar Background Tint > Preserve HP color on all unit frames"] = "Открывается: «Глобальный стиль» > «Цвета» > «Оттенок фона полосы» > «Сохранить цвет HP на всех фреймах юнитов».",
    ["Opens: Global Style > Colors > Bar Colors"] = "Открывается: «Глобальный стиль» > «Цвета» > «Цвета полос».",
    ["Opens: Global Style > Colors > Class Bar Colors"] = "Открывается: «Глобальный стиль» > «Цвета» > «Цвета панели классов».",
    ["Opens: Global Style > Fonts"] = "Открывается: Глобальный стиль > Шрифты.",
