    ["Opens: Player > Portrait"] = "Открывается: Игрок > Портрет.",
    ["Opens: Player > Status icons > Indicator: Level"] = "Открывается: Плеер > Значки состояния > Индикатор: Уровень.",
    ["Opens: Player > Text"] = "Открывается: Плеер > Текст.",
    ["Opens: Player > Transparency"] = "Открывается: Плеер > Прозрачность.",
    ["Opens: Profiles > Export / Import"] = "Открывается: Профили > Экспорт/Импорт.",
    ["Opens: Profiles > Profile Management / Export / Import"] = "Открывается: Профили > Управление профилями/Экспорт/Импорт.",
