L["|cff00ff00MSUF:|r Total absorb amount in HP text DISABLED."] = "|cff00ff00MSUF:|r Общее поглощение в тексте здоровья ОТКЛЮЧЕНО."
L["|cff00ff00MSUF:|r Total absorb amount in HP text ENABLED."] = "|cff00ff00MSUF:|r Общее поглощение в тексте здоровья ВКЛЮЧЕНО."
