L["|cffff0000MSUF WARNING:|r This will delete |cffff0000ALL|r MSUF profiles & settings for this account."] = "|cffff0000ПРЕДУПРЕЖДЕНИЕ MSUF:|r Это удалит |cffff0000ВСЕ|r профили и настройки MSUF для этой учетной записи."
