L["|cffff0000MSUF:|r Cannot do FULL reset while in combat."] = "|cffff0000MSUF:|r Полный сброс невозможен в бою."
L["|cffff0000MSUF:|r Cannot reset while in combat."] = "|cffff0000MSUF:|r Сброс невозможен в бою."
L["|cffff0000MSUF:|r Factory defaults are not available; nothing was reset."] = "|cffff0000MSUF:|r Заводские настройки недоступны; ничего не сброшено."
L["|cffff0000MSUF:|r DB not initialized."] = "|cffff0000MSUF:|r База данных не инициализирована."
L["|cffff0000MSUF:|r FULL RESET executed - all MSUF profiles & settings deleted for this account."] = "|cffff0000MSUF:|r ПОЛНЫЙ СБРОС выполнен - все профили и настройки MSUF для этой учетной записи удалены."
L["|cffff0000MSUF:|r Usage: /msuf gfhoverdebug on|off|status"] = "|cffff0000MSUF:|r Использование: /msuf gfhoverdebug on|off|status"
L["|cffff5555MSUF|r: Can't reload UI in combat. Leave combat, then type /reload."] = "|cffff5555MSUF|r: нельзя перезагрузить интерфейс в бою. Выйдите из боя, затем введите /reload."
L["|cffff6060CTRL required:|r |cffffffffhold |r|cff55ff55CTRL + Left-Click|r|cffffffff to confirm the anchor target.|r"] = "|cffff6060Требуется CTRL:|r |cffffffffудерживайте |r|cff55ff55CTRL + левый клик|r|cffffffff, чтобы подтвердить цель якоря.|r"
L["|cffffcc00MSUF:|r Full reset cancelled. If you still want it, type:"] = "|cffffcc00MSUF:|r Полный сброс отменен. Если он все еще нужен, введите:"
L["|cffffcc00MSUF:|r Then click: MSUF Menu > Advanced > Factory Reset (or type /reload)."] = "|cffffcc00MSUF:|r Затем нажмите: Меню MSUF > Дополнительно > Заводской сброс (или введите /reload)."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf fullreset confirm|r to stage the reset."] = "|cffffcc00MSUF:|r Введите |cffffff00/msuf fullreset confirm|r, чтобы подготовить сброс."
L["|cffffcc33No named frame found under cursor.|r |cffffffffTry a different spot.|r"] = "|cffffcc33Под курсором не найден именованный фрейм.|r |cffffffffПопробуйте другое место.|r"
L["|cffffd700MSUF:|r Castbar Edit Mode |cff00ff00ON|r drag player/target/focus castbars with the mouse."] = "|cffffd700MSUF:|r Режим редактирования полос применения |cff00ff00ВКЛ|r: перетаскивайте полосы игрока/цели/фокуса мышью."
L["|cffffd700MSUF:|r Castbar Edit Mode |cffff0000OFF|r."] = "|cffffd700MSUF:|r Режим редактирования полос применения |cffff0000ВЫКЛ|r."
L["|cffffd700MSUF:|r Rounded frame texture changed. Reload the UI with /reload."] = "|cffffd700MSUF:|r Текстура скругленных фреймов изменена. Перезагрузите интерфейс командой /reload."
L["|cffffd700MSUF:|r Use /msuf to open the menu."] = "|cffffd700MSUF:|r Используйте /msuf, чтобы открыть меню."
L["|cffffff00MSUF:|r Reloading UI to rebuild clean defaults..."] = "|cffffff00MSUF:|r Перезагрузка интерфейса для восстановления чистых значений по умолчанию..."
L["|cffffff00MSUF:|r Reset staged. Please type |cff00ff00/reload|r OR use: MSUF Menu > Advanced > Factory Reset."] = "|cffffff00MSUF:|r Сброс подготовлен. Введите |cff00ff00/reload|r ИЛИ используйте Меню MSUF > Дополнительно > Заводской сброс."
L["|cffffffffHover a frame, then hold |r|cff55ff55CTRL + Left-Click|r|cffffffff to anchor.  |  Right-Click or Escape cancels.|r"] = "|cffffffffНаведите на фрейм, затем удерживайте |r|cff55ff55CTRL + левый клик|r|cffffffff для привязки.  |  Правый клик или Escape отменяет.|r"
L["|cffffffffLeft Click:|r Open MSUF"] = "|cffffffffЛевый клик:|r открыть MSUF"
L["|cffffffffLeft Click:|r Open MSUF Menu"] = "|cffffffffЛевый клик:|r открыть меню MSUF"
