L["A %s in your group can provide this."] = "%s в вашей группе может это предоставить."
L["A calmer setup command center: start with movement, frames, group frames, or a safe profile import."] = "Более спокойный центр настройки: начните с перемещения, рамок, групповых рамок или безопасного импорта профиля."
L["Active Spell Indicators:"] = "Активные индикаторы заклинаний:"
L["Add menu scroll edge bounce."] = "Добавлен отскок у краев прокрутки меню."
L["Add Spell..."] = "Добавить заклинание..."
L["Added and refined the Menu2 search module."] = "Добавлен и улучшен модуль поиска Menu2."
L["Added backend compatibility hardening across MSUF modules."] = "Добавлено усиление совместимости внутренней части между модулями MSUF."
L["Added centralized font registry support for the unit frame runtime."] = "Добавлена централизованная регистрация шрифтов для фреймов юнитов во время работы."
L["Added class-colored bar background support across unit and group frames."] = "Добавлена поддержка фона полос цвета класса для юнитов и групп."
L["Added core swap recolor runtime support."] = "Добавлена поддержка перекраски при смене основной системы во время работы."
L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "Добавлена поддержка фрейма Цель фокуса в настройках юнитов, режиме редактирования, предпросмотрах, целях копирования, тексте, значках и обновлениях во время работы."
L["Added improved on/off switch visuals."] = "Добавлен улучшенный вид переключателей включения и выключения."
L["Added more Menu2 cards and refined menu structure."] = "Добавлены карточки Menu2 и улучшена структура меню."
L["Added more Menu2 cards to group and unit sections."] = "Добавлены карточки Menu2 в разделы групп и юнитов."
L["Added new Menu2 search module and improved search/guidance text."] = "Добавлен новый поиск Menu2 и улучшены тексты поиска/подсказок."
L["Added new UI/media assets for switches and rounded/superellipse visuals."] = "Добавлены новые ресурсы интерфейса и медиа для переключателей, скругленных элементов и визуалов в форме суперэллипса."
L["Added raid group number display next to unit names."] = "Добавлено отображение номера рейдовой группы рядом с именами."
L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "Добавлена переработанная раскладка карточек Menu2 для страниц юнитов, групп, аур, индикаторов, полос и расширенных настроек."
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "Добавлены скругленные фреймы с настройками по поверхностям для юнитов, групп, полос, подсветок, наложений, поглощений и индикаторов."
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "Добавлены медиа скругленных масок для активных фреймов юнитов и групп, а также для предпросмотра Menu2."
L["Added Rounded Texture controls under Global Style > Bars with per-surface toggles, search coverage, localization, preview support, and a reload prompt."] = "Добавлены настройки Скругленная текстура в Глобальный стиль > Полосы с переключателями по поверхностям, поиском, локализацией, предпросмотром и запросом перезагрузки."
