L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "Режим Blizzard позволяет WoW размещать выбранные типы аур. Пользовательский режим MSUF позволяет MSUF управлять размером, ростом, позицией, фильтрами и стилем. Подсветка рассеивания MSUF сохраняет значки Blizzard, но позволяет MSUF показывать границу, свечение и наложение рассеивания."
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "Рендерер Blizzard все еще активен, но эта группа работает как MSUF Custom, потому что ее переключатель Использовать Blizzard выключен. Другие активные типы аур Blizzard все еще могут показывать совпадающие заклинания, поэтому возможны дубликаты."
