L["Your MSUF 6.0 highlights"] = "Ваши основные моменты MSUF 6.0"
L["Your current profile stays unchanged. Review %d new highlights and choose only what you want to configure."] = "Ваш текущий профиль останется неизменным. Просмотрите новые функции %d и выберите только то, что вы хотите настроить."
L["CURRENT PROFILE: %s - NO SETTINGS WILL BE CHANGED"] = "ТЕКУЩИЙ ПРОФИЛЬ: %s – НИКАКИЕ НАСТРОЙКИ ИЗМЕНЕНЫ НЕ БУДЕТ."
