L["Back"] = "Назад"
L["Skip tour"] = "Пропустить тур"
L["See the remaining highlights before deciding to skip them."] = "Посмотрите оставшиеся основные моменты, прежде чем решить пропустить их."
L["Skip %d remaining highlights?"] = "Пропустить оставшиеся моменты %d?"
L["Your profile will stay safe, but you will leave these %d new configuration areas unexplored:"] = "Ваш профиль останется в безопасности, но вы оставите эти новые области конфигурации %d неисследованными:"
L["Show me the highlights"] = "Покажи мне основные моменты"
L["Skip all %d and continue"] = "Пропустить все %d и продолжить."
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "Пропуск закрывает только этот релизный тур. Все настройки остаются доступными в Меню2."
L["Custom Aura tracking on Unitframes"] = "Пользовательское отслеживание ауры на Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "Создайте до трёх собственных полос на фреймах игрока, цели, фокуса и босса, добавьте точные SpellID баффов или дебаффов и отслеживайте свои DoT на цели в подобранной для класса полосе."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "Ваши фреймы MSUF могут действовать как сфокусированные трекеры в стиле WeakAura со значками, таймерами, полосами продолжительности и полнокадровыми эффектами оттенка, границы, свечения или пульсации."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "три трекера Custom Aura для каждого поддерживаемого Unitframe, точные белые списки заклинаний и полнокадровые эффекты"
L["Build a Custom tracker"] = "Создайте собственный трекер"
L["Aura settings in the right place"] = "Настройки аур в нужном месте"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "Настройка и индивидуальное оформление теперь находятся в соответствующих меню рамок юнитов и группы/рейда. Внешний вид > Ауры содержит расширенные общие стили."
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "Настройте каждую рамку в её контексте, а затем используйте раздел Ауры для общих форм значков, рамок, теней, цветов и интервалов."
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "настройки аур для каждой рамки и расширенное общее оформление в разделе Внешний вид > Ауры"
L["Open shared Aura styles"] = "Открыть общие стили аур"
L["Adaptive Party and Raid layouts"] = "Адаптивные макеты групп и рейдов"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "Группа, рейд и эпохальный рейд получили адаптивные компоновки с масштабированием, фильтры и чёрные списки аур для каждой полосы, отдельную страницу Dispel Overlay, а вы решаете для каждого типа группы, кто рисует фреймы - MSUF или Blizzard."
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "Одна настройка группы проходит с вами путь от подземелья на пятерых до рейда, и вы для каждой полосы решаете, каким аурам вообще позволено появляться."
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "адаптивные компоновки групп и масштабирование, групповые фильтры и чёрные списки аур, страницу Dispel Overlay и выбор поставщика фреймов для каждой группы"
L["Open Group Layout"] = "Открытый макет группы"
L["New health values and text formats"] = "Новые значения здоровья и текстовые форматы"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "Текст здоровья может показывать сокращённые или полные значения с более единым форматированием, а новый слой потерянного максимального здоровья отмечает сниженный максимум на фреймах юнитов и групп."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Вы можете выбрать компактную читаемость или точные цифры, не отказываясь от уже используемого макета."
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "новые сокращения здоровья, полные значения, форматы текста и слой потерянного максимального здоровья"
L["Open HP Text Editor"] = "Открыть редактор текста здоровья"
L["More flexible class resources"] = "Более гибкие ресурсы классов"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Ресурсы классов получили отдельные макеты, дополнительные формы и более точные цвета для каждого слота и полного состояния."
L["You can move class information where your eyes already are and make important states easier to read."] = "Вы можете переместить информацию о классе туда, где уже находятся ваши глаза, и облегчить чтение важных состояний."
L["detached class resources, new shapes and per-state colors"] = "ресурсы отдельных классов, новые формы и цвета для каждого состояния."
L["Configure Class Resources"] = "Настройка ресурсов класса"
L["Cast target text"] = "Трансляция целевого текста"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "На панелях применения цели, фокуса и босса теперь можно указать, на кого нацелено текущее заклинание, с помощью специального стиля текста."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Вы можете определить место назначения важного применения, не отвлекая внимание от панели применения."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "имена каст-целей и стиль их текста в фреймах Target, Focus и Boss"
L["Open Target Cast Bar"] = "Открытая полоса применения цели"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "Прежде чем использовать действия при первой загрузке, просмотрите или пропустите основные сведения о выпуске на информационной панели."
L["Priority Frames for the units that matter"] = "Приоритетные рамки для тех, кто важен"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "Закрепите вручную до пяти участников группы или позвольте MSUF выбирать танков автоматически, и получите отдельную полосу, которая не перестраивается посреди боя."
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "Те, за кем нужно следить, остаются на одном и том же месте экрана, сохраняя вид группы или рейда и привычный клик-каст."
L["Priority Frames, manual and automatic pinning, and their own placement"] = "приоритетные рамки, ручное и автоматическое закрепление и их собственное размещение"
L["Set up Priority Frames"] = "Настроить приоритетные рамки"
L["One Colors page with click-to-paint"] = "Одна страница цветов с покраской по клику"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "Все цвета переехали на одну страницу и разделены на рабочие области: Игрок и цель, Группа и рейд, Полоса заклинаний, Ауры, Энергия и Ресурсы класса, у каждой свой живой предпросмотр."
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "Можно щёлкнуть элемент в предпросмотре и покрасить его, вместо того чтобы искать нужный образец, и повторно взять любой цвет из недавней или сохранённой палитры."
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "перестроенную страницу цветов, предпросмотр с покраской по клику, палитры и новый выбор цвета"
L["Open the Colors page"] = "Открыть страницу цветов"
L["One 0-30 layer scale for everything"] = "Единая шкала слоёв 0-30 для всего"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "Тексты, значки состояния, ауры, рамки, контуры полос, групповые индикаторы и ресурсы класса упорядочиваются по одной общей шкале слоёв 0-30."
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "Вы решаете, что именно рисуется поверх чего, а обзор слоёв рядом с любым ползунком слоя показывает всю стопку сразу."
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "общую для аддона шкалу слоёв 0-30 и обзор слоёв"
L["MSUF Edit Mode, rebuilt"] = "Режим редактирования MSUF, перестроенный"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "Режим редактирования получил закрепляемую панель инструментов, переработанные быстрые меню на каждой рамке и отмену с повтором, которые работают так же, как в меню."
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "Можно двигать, менять размер и копировать рамки прямо на экране и отменять любую ошибку, не открывая меню заново."
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "новую панель инструментов режима редактирования, его быстрые меню и общую отмену с повтором"
L["Start Edit Mode"] = "Запустить режим редактирования"
L["Spell Indicators on Group Frames"] = "Spell Indicators на групповых фреймах"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "Отслеживайте выбранные баффы на фреймах группы и рейда значком, квадратом, полосой или числом, с собственными списками заклинаний и угловыми индикаторами."
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "Вы видите отсутствующие или истекающие внешние защиты и ключевые баффы прямо на фреймах, с сиянием при истечении, подсветкой полосы здоровья и эффектами на весь фрейм."
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "Spell Indicators с собственными списками аур, угловыми индикаторами и предупреждениями об истечении"
L["Open Spell Indicators"] = "Открыть Spell Indicators"
L["Fill Direction for Health and Power"] = "Направление заполнения здоровья и ресурса"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "Каждый фрейм юнита может заполнять здоровье и ресурс слева направо, справа налево, снизу вверх или сверху вниз."
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "Вертикальные и зеркальные компоновки полос становятся настройкой для каждого фрейма - такого сейчас не предлагает ни один другой аддон юнитфреймов."
L["the per-frame Fill Direction control for Health and Power bars"] = "направление заполнения полос здоровья и ресурса для каждого фрейма"
L["Choose a Fill Direction"] = "Выбрать направление заполнения"
L["Portraits: attached, detached or overlay"] = "Портреты: прикреплённые, отдельные или поверх"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "Портрет может оставаться у фрейма, свободно перемещаться или рисоваться поверх полосы здоровья - с независимым размером, привязкой по девяти точкам, прозрачностью и перемещаемым зумом."
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "Становятся возможны прямоугольные портреты и портреты-водяные знаки, а кольца Relief и повторяющие форму рамки обрамляют квадратные, круглые, скруглённые и ромбовидные портреты."
L["the new portrait placement modes, Relief rings and shape-following portrait borders"] = "новые режимы размещения портретов, кольца Relief и повторяющие форму рамки"
L["Open Portrait settings"] = "Открыть настройки портрета"
L["Status icon packs"] = "Наборы значков статуса"
L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "Роль, лидер, рейдовая метка, проверка готовности и любой другой значок статуса могут переключаться между двенадцатью встроенными стилями или вашими значками - для каждого индикатора отдельно."
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "Значки статуса наконец могут соответствовать стилю вашего интерфейса вместо графики Blizzard, а внешние наборы регистрируются через SharedMedia."
L["the twelve status icon styles and per-indicator custom icons"] = "двенадцать стилей значков статуса и собственные значки для каждого индикатора"
L["Pick an icon style"] = "Выбрать стиль значков"
