L["Hides this aura from the regular Buff icons while this spell indicator is enabled. External-defensive Spell Icons follow the active External Defensives container's Auto-blacklist from Buffs setting."] = "Скрывает эту ауру из обычных значков положительных эффектов, пока включён индикатор заклинания. Индикаторы внешней защиты следуют настройке автоматического скрытия активного контейнера «Внешняя защита»."
L["While External Defensives is visible and Max is above 0, hides every aura Blizzard classifies as EXTERNAL_DEFENSIVE from the normal Buffs container. If External Defensives is disabled, those auras remain visible in Buffs."] = "Пока «Внешняя защита» видима и максимум больше 0, скрывает из обычного контейнера положительных эффектов все ауры, которые Blizzard классифицирует как EXTERNAL_DEFENSIVE. Если «Внешняя защита» отключена, эти ауры остаются видимыми среди положительных эффектов."
