L["Try \"raid auras\" or \"how do I make text bigger?\""] = "Попробуйте «ауры рейда» или «как увеличить текст?»"
L["Skipping leaves Spell Icons unchanged; you can find them later with Menu Search."] = "Если пропустить этот шаг, значки заклинаний не изменятся; позже их можно найти через поиск по меню."
L["Finish the tour and use Menu Search to find other settings."] = "Завершите обучение и используйте поиск по меню, чтобы найти другие настройки."
L["MISSION COMPLETE - Press Finish to return to the Dashboard."] = "МИССИЯ ВЫПОЛНЕНА — нажмите «Готово», чтобы вернуться на панель."
L["Finish setup"] = "Завершить настройку"
L["Find settings with Search"] = "Найдите настройки через поиск"
L["Search Menu2 in everyday language to jump to the exact setting. Search only includes controls available in your active modules."] = "Ищите в Menu2 обычными словами, чтобы сразу перейти к нужной настройке. Поиск охватывает только элементы управления включённых модулей."
L["Finish opens the Dashboard, where you can search settings across the active modules."] = "«Готово» открывает панель, где можно искать настройки во всех включённых модулях."
L["Try searches such as 'Party frame width', 'Spell Icons', or 'Class Resources'. Search opens the matching setting in Menu2."] = "Попробуйте запросы вроде «ширина рамок группы», «значки заклинаний» или «ресурсы класса». Поиск открывает нужную настройку в Menu2."
L["Finish returns to the Dashboard. Smart Search stays ready for settings and questions."] = "«Готово» возвращает на панель. Умный поиск по-прежнему готов к настройкам и вопросам."
L["Use the Dashboard for common tasks, or type a setting or full question into Smart Search."] = "Используйте панель для частых задач или введите настройку или целый вопрос в умный поиск."
L["Anything else? Just ask"] = "Что-то ещё? Просто спросите"
