L["Two arrows point to a movable frame. Drag it once; Next unlocks after a real position change."] = "Две стрелки указывают на подвижную рамку. Перетащите его один раз; Далее разблокируется после реального изменения позиции."
L["Type a new value, then press Enter."] = "Введите новое значение и нажмите Enter."
L["UNLOCK, THEN CHANGE IT - Enable Corner Indicators, choose a slot, then select Custom Spell when requested."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ ЕГО. Включите угловые индикаторы, выберите слот, затем выберите «Пользовательское заклинание», когда потребуется."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spec, then press a tracked spell tile."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Включите индикаторы заклинаний, выберите специализацию, затем нажмите на плитку отслеживаемого заклинания."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then select a Frame Effect."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Включите индикаторы заклинаний, выберите заклинание, затем выберите эффект фрейма."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then set Indicator Type."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Включите индикаторы заклинаний, выберите заклинание, затем установите тип индикатора."
L["UNLOCK, THEN CHANGE IT - Enable the parent feature in this section first."] = "РАЗБЛОКИРУЙТЕ, ЗАТЕМ ИЗМЕНИТЕ. Сначала включите родительскую функцию в этом разделе."
L["UNLOCK, THEN CHANGE IT - Turn on Spell Indicators in the earlier checkpoint; use Back if you skipped it."] = "РАЗБЛОКИРОВАТЬ, ЗАТЕМ ИЗМЕНИТЬ — включите индикаторы заклинаний на предыдущей контрольной точке; используйте «Назад», если вы пропустили его."
L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "Значки состояния блока находятся на каждой странице объекта. Индикаторы групповых заклинаний находятся в разделе «Групповые рамки» > «Ауры»; Статус группы и угловые индикаторы находятся в разделе «Групповые рамки» > «Состояние и индикаторы»."
