-- Акцентный цвет меню (Misc > Поведение меню).
L["Menu accent color"] = "Акцентный цвет меню"
L["Midnight (default)"] = "Midnight (по умолчанию)"
L["Class color"] = "Цвет класса"
L["Custom accent color"] = "Свой акцентный цвет"
L["Ember"] = "Ember"
L["Jade"] = "Jade"
L["Violet"] = "Violet"
L["Reload"] = "Перезагрузить"
L["Midnight keeps the stock blue accent. Class color follows this character; the accent applies after a UI reload."] = "Midnight сохраняет стандартный синий акцент. Цвет класса следует этому персонажу; акцент применяется после перезагрузки интерфейса."
L["The menu accent color is baked in while the menu is built, so a UI reload is required to apply it.\n\nReload now?"] = "Акцентный цвет меню встраивается при построении меню, поэтому для его применения требуется перезагрузка интерфейса.\n\nПерезагрузить сейчас?"
L["Menu accent colors"] = "Акцентные цвета меню"
L["The MSUF menu can now follow your class color, a curated preset like Ember, Jade or Violet, or any custom color."] = "Меню MSUF теперь может использовать цвет вашего класса, готовый пресет вроде Ember, Jade или Violet либо любой свой цвет."
L["The whole menu re-tints to your accent - surfaces, navigation and controls - applied after a UI reload."] = "Всё меню окрашивается в ваш акцент - поверхности, навигация и элементы управления - после перезагрузки интерфейса."
L["The accent colors navigation, tabs and highlights; panels stay midnight unless you turn on Tint menu surfaces. Applied after a UI reload."] = "Акцент окрашивает навигацию, вкладки и подсветку; панели остаются midnight, пока вы не включите «Тонировать поверхности меню». Применяется после перезагрузки интерфейса."
L["Tint menu surfaces"] = "Тонировать поверхности меню"
L["Zoom %d%%"] = "Масштаб %d%%"
L["Opacity %d%%"] = "Непрозрачность %d%%"
L["Off (default): the accent colors buttons, tabs and highlights while panels stay midnight. On: panels, borders and the navigation rail are rotated onto the accent hue too. Success, warning and danger colors never change."] = "Выкл. (по умолчанию): акцент окрашивает кнопки, вкладки и подсветку, а панели остаются midnight. Вкл.: панели, границы и панель навигации также переводятся в оттенок акцента. Цвета успеха, предупреждения и опасности никогда не меняются."
L["class-color, preset and custom accent options for the MSUF menu"] = "акцент по цвету класса, пресеты и свой акцентный цвет для меню MSUF"
L["Pick a menu accent"] = "Выбрать акцент меню"

-- 6.0 upgrade highlight: the rebuilt rounded corner style.
L["Rounded frames, corner for corner"] = "Скруглённые рамки, угол в угол"
L["Rounded unit and group frames now share one clean corner style with five strength levels, used by Health, embedded or detached Power, frame outlines and the aggro, dispel and highlight borders."] = "Скруглённые рамки юнитов и группы теперь используют единый аккуратный стиль углов с пятью уровнями силы - для здоровья, встроенного или отделённого ресурса, контуров рамки, а также рамок угрозы, рассеивания и подсветки."
L["Every rounded element follows the same geometry, so corners no longer disagree with each other or lose their mask after a reload."] = "Каждый скруглённый элемент следует одной геометрии, поэтому углы больше не расходятся между собой и не теряют маску после перезагрузки."
L["the rebuilt rounded corner style and its five strength levels"] = "переработанный стиль скруглённых углов и его пять уровней силы"
