L["|cffffcc00MSUF:|r Repeat |cffffff00/msuf delete %s|r to delete that profile for good."] = "|cffffcc00MSUF:|r Повторите |cffffff00/msuf delete %s|r, чтобы окончательно удалить этот профиль."
