L["The resource color follows Player power. A matched background is derived from Health instead."] = "Цвет ресурса следует ресурсу игрока. Подходящий фон вместо этого выводится из здоровья."
L["The foreground follows the selected HP color mode. Dark Mode uses the shared dark-tone control."] = "Передний план следует выбранному режиму цвета здоровья. Тёмный режим использует общий регулятор тёмного тона."
L["Foreground follows the selected group color mode; editable group colors are shared by Party, Raid and Mythic Raid."] = "Передний план следует выбранному режиму цвета группы; редактируемые цвета группы общие для группы, рейда и мифического рейда."
L["Health and Power gradient colors for the selected Bars scope."] = "Цвета градиента здоровья и ресурса для выбранной области полос."
L["Colors available to the border modes in this card."] = "Цвета, доступные режимам рамки в этой карточке."
L["Shared castbar background and outline colors."] = "Общие цвета фона и контура полосы заклинания."
L["Player colors follow the active override mode."] = "Цвета игрока следуют активному режиму переопределения."
L["The shown colors follow the selected indicator style."] = "Показанные цвета следуют выбранному стилю индикатора."
L["These colors are shared from the Colors page."] = "Эти цвета берутся со страницы «Цвета»."
L["Used when melee-range coloring is enabled."] = "Используется, когда включена окраска по дистанции ближнего боя."
L["Used by the Castbar icon-border style."] = "Используется стилем рамки значка полосы заклинания."
L["Used only when the power bar is detached from the frame."] = "Используется только когда полоса ресурса отделена от рамки."
L["Outline and fill behavior."] = "Поведение контура и заливки."
L["Opacity values used by range and offline states."] = "Значения непрозрачности для состояний дистанции и отключения."
L["Width can use manual bounds or follow another frame."] = "Ширина может задаваться вручную или следовать другой рамке."
L["Power textures live on the Bars page."] = "Текстуры ресурса находятся на странице «Полосы»."
L["When anchored here, Player power settings are managed by Class Resources."] = "При закреплении здесь настройки ресурса игрока управляются «Ресурсами класса»."
L["Font face follows Shared; text and color mode mirror Player HP."] = "Шрифт следует общему; текст и режим цвета повторяют здоровье игрока."
L["Local HP text uses shared face settings and a fixed white color."] = "Локальный текст здоровья использует общие настройки шрифта и фиксированный белый цвет."
L["Synchronized with Text Colors in the Fonts menu for this scope."] = "Синхронизировано с «Цветами текста» в меню шрифтов для этой области."
L["Open the shared font and colors used by every Aura scope."] = "Открывает общий шрифт и цвета, используемые всеми областями аур."
L["Tints unit-frame health bars when a configured debuff condition is active."] = "Окрашивает полосы здоровья рамок при выполнении заданного условия дебаффа."
L["Shows a symbol naming the dispel type of an active debuff."] = "Показывает символ с типом рассеивания активного дебаффа."
L["Shows the raid subgroup number from the raid roster."] = "Показывает номер подгруппы из состава рейда."
L["Shows the raid subgroup number. Party frames only display it while you are in an actual raid group."] = "Показывает номер подгруппы. Рамки группы отображают его только в настоящем рейде."
L["Independent of mouseover. Marks your current target in the selected group-frame types."] = "Не зависит от наведения мыши. Отмечает текущую цель в выбранных типах групповых рамок."
L["Configure target highlighting in Appearance > Miscellaneous > Frame Highlights."] = "Настройте подсветку цели в «Оформление > Разное > Подсветка рамок»."
L["Configure the color used by the Solid and Custom portrait border styles."] = "Задаёт цвет для стилей рамки портрета «Сплошной» и «Пользовательский»."
L["Configure the optional portrait background color."] = "Задаёт необязательный цвет фона портрета."
L["Configure the Party portrait border color and opacity."] = "Задаёт цвет и непрозрачность рамки портрета в группе."
L["Scales frame size, fonts, and icons proportionally."] = "Пропорционально масштабирует размер рамки, шрифты и значки."
L["Buff/debuff positions stay relative to their anchors."] = "Позиции баффов и дебаффов остаются относительно их привязок."
L["Automatically scale by group size."] = "Автоматически масштабировать по размеру группы."
L["Drag rows with mouse to reorder."] = "Перетаскивайте строки мышью, чтобы изменить порядок."
