L["Right-click to follow the shared castbar text color again."] = "Щёлкните правой кнопкой, чтобы снова следовать общему цвету текста полосы заклинания."
L["Color for the selected text indicator. Right-click to follow the frame font color again."] = "Цвет выбранного текстового индикатора. Щёлкните правой кнопкой, чтобы снова следовать цвету шрифта рамки."
L["Castbar text follows the shared Fonts settings until this text gets its own color."] = "Текст полосы заклинания следует общим настройкам шрифта, пока у него нет собственного цвета."
L["Font style follows the Fonts menu for this frame; the color can be set per indicator."] = "Стиль шрифта следует меню шрифтов этой рамки; цвет задаётся для каждого индикатора."
L["Each castbar text can override the shared castbar text color. Target text exists on Target and Focus only."] = "Каждый текст полосы заклинания может переопределить общий цвет. Текст цели есть только у Цели и Фокуса."
L["Color for a single text indicator on one frame. Unset indicators follow that frame's font color."] = "Цвет одного текстового индикатора на одной рамке. Без своего цвета индикатор следует шрифту рамки."
L["Aura Style > Defensive Buffs can follow the frame portrait shape."] = "Стиль Ауры > Защитные баффы может повторять форму портрета фрейма."
L["Cooldown timer urgency plus shared icon border and shadow colors."] = "Срочность таймера перезарядки, а также общие цвета границы и тени значка."
L["Follow shared settings"] = "Следовать общим настройкам"
L["Icon Shape"] = "Форма значка"
L["Keeps Icon Shape synchronized with Aura Style > Shared while the remaining Group Aura settings stay local."] = "Синхронизирует Форму значка со Стилем Ауры > Общие, а остальные настройки аур группы остаются локальными."
L["Shared icon shape"] = "Общая форма значка"
L["Visibility modes apply only to unit and group frames. Aura tooltips use their own Show Tooltip switches; even Never does not override them. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Режимы видимости применяются только к фреймам юнитов и группы. Подсказки аур используют собственные переключатели Показать подсказку; даже Никогда их не отменяет. Ауры лишь повторяют выбранный вид Blizzard/MSUF и положение курсора."
L["Applies to the entire castbar: bar, icon, all text, effects, and border. All MSUF elements share this 0-30 order; every part of layer 30 draws above every part of layer 29."] = "Применяется ко всей полосе произнесения: полоса, значок, все тексты, эффекты и граница. Все элементы MSUF используют этот порядок 0-30; любая часть слоя 30 рисуется поверх любой части слоя 29."
L["Display: "] = "Отображение: "
L["Enemy debuffs: hide only exact noisy SpellIDs. Selected Dots on target are handled automatically by that scope's Auto-blacklist toggle."] = "Дебаффы противника: скрывайте только точные шумные SpellID. Выбранные DoT на цели обрабатываются автоматически переключателем автоматического чёрного списка этой области."
L["Icon"] = "Значок"
