--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "Всегда скрыт"
L["Blizzard Raid Manager"] = "Диспетчер рейда Blizzard"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "Вкладка Blizzard у левого края экрана с проверкой готовности, метками рейда и фильтрами ролей. Это один общий фрейм, поэтому настройка одинакова для группы, рейда и мифического рейда."
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "Скрывает диспетчер рейда, пока его не коснётся курсор. Проверка готовности, метки рейда и фильтры ролей остаются доступными, а развёрнутая панель остаётся видимой, пока вы не свернёте её снова."
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "Постоянно держит диспетчер рейда невидимым и не перехватывающим щелчки. Верните настройку, чтобы снова добраться до его кнопок."
L["Show on mouseover"] = "Показывать при наведении"
L["Automatic"] = "Автоматически"
L["Always visible"] = "Всегда виден"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "Скрывает диспетчер рейда, пока MSUF предоставляет активные групповые рамки, и в остальных случаях оставляет его WoW. MSUF всегда вёл себя именно так."
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "Оставляет диспетчер рейда доступным даже при включённых групповых рамках MSUF. Выберите это, если вам всё ещё нужны его проверка готовности, метки рейда и фильтры ролей."
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "Общая настройка для группы, рейда и мифического рейда. «Автоматически» держит вкладку скрытой, пока MSUF предоставляет групповые рамки."
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "Обнаружен %s: глобальная привязка следует за менеджером основных восстановлений. Отключите её кнопкой Cooldown в режиме редактирования MSUF."
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "Обнаружен %s: привязка к менеджеру восстановлений отключена. Включите её кнопкой Cooldown в режиме редактирования MSUF."
L["Cooldown Manager anchoring (%s)"] = "Привязка к менеджеру восстановления (%s)"
L["Global anchor (%s Anchor)"] = "Глобальная привязка (привязка %s)"
L["Fades all four outer edges; 0% keeps the original texture."] = "Смягчает все четыре внешних края; 0% сохраняет исходную текстуру."

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1 показывает заданный размер ауры в пикселях."
L["Aura Options"] = "Параметры ауры"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "Параметры ауры и Стиль Ауры относятся к этому UnitFrame. Глобальный вид значков: Внешний вид > Стиль Ауры."
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "Ниже этого значения оставшееся время может отображаться с одним знаком после запятой. Значение 0 оставляет только целые секунды."
L["Buff Appearance"] = "Внешний вид баффов"
L["Debuff Appearance"] = "Внешний вид дебаффов"
L["Global Aura Appearance: Buffs"] = "Глобальный внешний вид аур: Баффы"
L["Global Aura Appearance: Debuffs"] = "Глобальный внешний вид аур: Дебаффы"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Цвета таймера общие для аур единиц/группы в реальном времени и всех предпросмотров. Цвета рамки и тени значков находятся в разделе Внешний вид > Ауры и задаются отдельно для каждого типа аур."
L["Click to open the setting that enables this layer."] = "Нажмите, чтобы открыть настройку, включающую этот слой."
L["Controls native Aura tooltips for Spell Icons only."] = "Управляет стандартными подсказками аур только для Значков заклинаний."
L["Cooldown text format"] = "Формат текста перезарядки"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "Копирует отображение баффов, дебаффов, внешних защитных эффектов и Значков заклинаний, включая масштаб значка, текст, заливку, полосы длительности и порядок. Параметры ауры, отслеживаемые Значки заклинаний и глобальная тема Внешнего вида не меняются."
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "Копирует видимость, макет, фильтры, точные и категорийные черные списки, слой отрисовки и параметры рассеивания групповых аур. Стиль Ауры и глобальная тема Внешнего вида не меняются."
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "Копирует видимость аур, макет, фильтры, черные списки, настройку пользовательских аур и отслеживаемые заклинания этого UnitFrame. Стиль Ауры и глобальная тема Внешнего вида не меняются."
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "Копирует отображение баффов, дебаффов, пользовательских аур, защитных эффектов игрока и DoT на цели этого UnitFrame, включая текст, заливку, масштаб значка, полосы длительности, пандемию и эффекты на весь фрейм. Параметры ауры и глобальная тема Внешнего вида не меняются."
L["Drag background (%dx)"] = "Перетаскивание фона (%dx)"
L["Drag to move. Arrow keys nudge."] = "Перетащите, чтобы переместить. Стрелки смещают по шагам."
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "Режим разблокировки EllesmereUI"
L["Exact X coordinate"] = "Точная координата X"
L["Exact Y coordinate"] = "Точная координата Y"
L["Fit shows the complete aura layout."] = "Вписать показывает полный макет аур."
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "Глобальная тема Внешнего вида выбирается только по типу ауры. Макет, фильтры, таймеры, текст и эффекты остаются привязанными к области в соответствующем UnitFrame или GroupFrame."
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "Индивидуальный Стиль редактируется здесь. Общая тема значков: Внешний вид > Стиль Ауры."
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "Макет, фильтры, списки и любой Стиль конкретного контейнера находятся в самом фрейме. Внешний вид > Стиль Ауры отвечает только за глобальную тему значков."
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "Отсчитывается от центра фрейма в предпросмотре. Положительные значения смещают вправо. Стрелки и перетаскивание изменяют одну и ту же позицию."
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "Отсчитывается от центра фрейма в предпросмотре. Положительные значения смещают вверх. Стрелки и перетаскивание изменяют одну и ту же позицию."
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "Включено (по умолчанию): фреймы MSUF отображаются в Режиме разблокировки EllesmereUI. Отключите, чтобы продолжить пользоваться собственным Режимом редактирования MSUF. Позиции профиля MSUF остаются основным источником."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "Откройте фрейм и разверните Ауры. У баффов и дебаффов есть собственные макет, фильтры, черные списки и Стиль; Пользовательские 1-3, Защитные баффы и DoT на цели показывают настройки, соответствующие их содержимому."
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "Открывает глобальную тему значков аур: рамка, тень, цвета, отступ рядов и стандартные чары оружия игрока. Индивидуальный Стиль этого GroupFrame остается здесь."
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "ПРЕДУПРЕЖДЕНИЕ О ПРОИЗВОДИТЕЛЬНОСТИ (12.1): Blizzard может выполнять OnUpdate в каждом фрейме для каждой видимой кнопки ауры, пока у ауры рассчитано окно пандемии, а не только пока показано предупреждение. Включайте только если вы принимаете эти потенциально высокие затраты в бою."
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Накладывает временную подсветку на активные GroupFrames, чтобы оценить наложение без настоящего рассеиваемого дебаффа. Отключается сама при закрытии этой страницы."
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Накладывает временную подсветку на активный UnitFrame, чтобы оценить наложение без настоящего рассеиваемого дебаффа. Отключается сама при закрытии этой страницы."
L["Position is controlled by the colored aura handle in Preview."] = "Положение задается цветным маркером ауры в Предпросмотре."
L["Preview position"] = "Положение предпросмотра"
L["Runtime Preview"] = "Предпросмотр в реальном времени"
L["Runtime Preview: live GroupFrames"] = "Предпросмотр в реальном времени: активные GroupFrames"
L["Runtime Preview: live UnitFrame"] = "Предпросмотр в реальном времени: активный UnitFrame"
L["Runtime Preview: live UnitFrame (drag)"] = "Предпросмотр в реальном времени: активный UnitFrame (перетаскивание)"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "Форма, рамка и тень: Внешний вид > Стиль Ауры > Баффы. Все настройки здесь остаются привязанными к области группы."
L["Shared Aura Style"] = "Общий Стиль Ауры"
L["Shared Aura Style: Buffs"] = "Общий Стиль Ауры: баффы"
L["Shared Aura Style: Debuffs"] = "Общий Стиль Ауры: дебаффы"
L["Shared Preview - "] = "Общий предпросмотр - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "Показывает временные символы на активном UnitFrame и позволяет перетащить их на нужное место без настоящего дебаффа. Отключается сам при закрытии этой страницы."
L["Spell Icon Style"] = "Стиль Значков заклинаний"
L["Spell Icon tooltip"] = "Подсказка Значков заклинаний"
L["Swipe Direction"] = "Направление заливки"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "Этот переключатель показывается только пока загружен EllesmereUI. После отключения MSUF сразу возвращается к собственному Режиму редактирования."
L["Use - / + or Ctrl + mouse wheel to zoom."] = "Используйте - / + или Ctrl + колесо мыши для масштабирования."
L["Use EllesmereUI Unlock Mode for MSUF"] = "Использовать Режим разблокировки EllesmereUI для MSUF"
L["Use the colored Texture handle in Preview for exact placement."] = "Для точного размещения используйте цветной маркер текстуры в Предпросмотре."
L["Zoom changes only this preview, not your Aura settings."] = "Масштаб меняет только этот предпросмотр, а не ваши настройки аур."

-- Menu localization pass 2026-08-06 (part 2): dropdown values, tooltips and labels routed through Tr() that the coverage extractor could not see.
