L["Shows or hides the %s dashboard section."] = "Показывает или скрывает раздел панели %s."
L["Source: player buffs · %d / %d predefined enabled · %d custom · passive talent procs included"] = "Источник: баффы игрока · включено предустановленных: %d / %d · пользовательских: %d · срабатывания пассивных талантов включены"
L["Source: this UnitFrame · Ownership: only mine · Harmful DoTs only · %d selected"] = "Источник: этот UnitFrame · Владение: только мои · только вредоносные DoT · выбрано: %d"
L["Stops tracking this buff in the custom container."] = "Прекращает отслеживание этого баффа в пользовательском контейнере."
