L["Track a debuff - Spell ID, link, or name"] = "Отслеживать дебафф - ID заклинания, ссылка или название"
L["Use Global (%s)"] = "Использовать глобальное (%s)"
L["|cff00b7ebMSUF|r: First-start preview re-armed (%s). Guided-tour progress was reset."] = "|cff00b7ebMSUF|r: предпросмотр первого запуска активирован заново (%s). Прогресс обучающего тура сброшен."
