-- Menu localization pass 2026-08-06 (part 7): entries that were still identity English.
L["Confirm anchoring"] = "Подтвердить привязку"
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Подтверждайте только если хотите, чтобы весь макет фрейма юнита перемещался вместе с вашими способностями."
L["Keep independent"] = "Оставить независимым"
L["MSUF detected %s."] = "MSUF обнаружил %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "Теперь MSUF привяжет глобальный макет фрейма юнита к Essential Cooldown Manager."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Ничего не сдвинется, пока вы не подтвердите ещё раз на следующем шаге. Если выбрать «Оставить независимым», привязку CDM можно включить в любой момент в Режиме редактирования MSUF или в разделе Юнит > Привязка меню MSUF."
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Ничего не сдвинется, пока вы не подтвердите ещё раз на следующем шаге. Позже это можно изменить в Режиме редактирования MSUF."
L["Second confirmation for %s."] = "Второе подтверждение для %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Привязать глобальный макет фрейма юнита к Essential Cooldown Manager?"
L["< HP"] = "< HP"
L["HP >"] = "HP >"
-- Menu localization pass 2026-08-06 (part 7): native Player resource pings.
L["Enable native Player resource pings (12.1)"] = "Включить встроенные пинги ресурсов игрока (12.1)"
L["Native Player resource pings"] = "Встроенные пинги ресурсов игрока"
L["Contextual pings over the MSUF Player frame can call out health and, when Blizzard supports it, mana. Blizzard does not expose separate Health/Power selection or Energy, Rage and Focus pings. The portrait keeps the normal Player unit ping and radial wheel."] = "Контекстные пинги на рамке игрока MSUF могут сообщать о здоровье и, когда это поддерживается Blizzard, о мане. Blizzard не предоставляет отдельный выбор «Здоровье/Ресурс» и пинги энергии, ярости или концентрации. Над портретом сохраняются обычный пинг игрока и радиальное меню."
L["Edits the selected element's X position. Positive values move right. Arrow keys and dragging update the same position."] = "Изменяет позицию X выбранного элемента. Положительные значения сдвигают его вправо. Стрелки и перетаскивание изменяют ту же позицию."
L["Edits the selected element's Y position. Positive values move up. Arrow keys and dragging update the same position."] = "Изменяет позицию Y выбранного элемента. Положительные значения сдвигают его вверх. Стрелки и перетаскивание изменяют ту же позицию."
L["Exact X position"] = "Точная позиция X"
L["Exact Y position"] = "Точная позиция Y"
L["External frame"] = "Внешняя рамка"
L["Next page"] = "Следующая страница"
L["Previous page"] = "Предыдущая страница"

L["UnitFrame Debuff blacklist"] = "Чёрный список отрицательных эффектов UnitFrame"
L["You can blacklist any debuff applied by the player on the %s UnitFrame using its exact Spell ID. The debuff on the unit can carry a different Spell ID than the spell you cast - use the ID from the debuff itself."] = "Можно добавить в чёрный список любой отрицательный эффект, наложенный игроком на UnitFrame %s, используя точный ID заклинания. Отрицательный эффект на цели может иметь ID заклинания, отличающийся от произнесенного заклинания - используйте ID самого эффекта."
L["Spell ID vs. aura ID"] = "ID заклинания и ID ауры"
L["The aura on the unit can use a different Spell ID than the spell you cast. Enter the ID shown on the aura itself. After adding, MSUF checks the live unit and warns when only a same-named aura with a different ID is active."] = "Аура на цели может использовать ID заклинания, отличающийся от произнесенного заклинания. Вводите ID самой ауры. После добавления MSUF проверяет цель и предупреждает, если активна только одноименная аура с другим ID."
L["%s (#%d) is active on this frame right now - blacklist entry verified."] = "%s (#%d) сейчас активен на этом фрейме - запись чёрного списка подтверждена."
L["#%d is not active on this frame, but %s is currently active as #%d. The aura's ID can differ from your cast's Spell ID."] = "#%d не активен на этом фрейме, но %s сейчас активен как #%d. ID ауры может отличаться от ID произнесенного заклинания."
L["Block #%d instead"] = "Заблокировать #%d вместо этого"
L["Active auras on this frame"] = "Активные ауры на этом фрейме"
L["Shows the result of the last scan: every readable aura with the exact ID it carried, plus everything captured earlier this session. Press Rescan to scan the current unit - blocking from this list always uses the aura's own ID. Secret auras cannot be listed."] = "Показывает результат последнего сканирования: каждую читаемую ауру с её точным ID, а также всё записанное за эту сессию. Нажмите «Обновить», чтобы просканировать текущую цель - блокировка из этого списка всегда использует ID самой ауры. Секретные ауры не могут быть перечислены."
L["No scan yet - click Rescan"] = "Сканирование ещё не выполнялось - нажмите «Обновить»"
L["Start combat scan"] = "Начать боевое сканирование"
L["Closes the menu and keeps scanning this frame's auras until combat ends or you press Stop. Every aura an addon can block is captured with its icon - auras Blizzard keeps secret cannot be blocked by any addon."] = "Закрывает меню и продолжает сканировать ауры этого фрейма, пока бой не закончится или вы не нажмёте «Стоп». Каждая аура, которую аддон вообще может заблокировать, записывается со значком - ауры, скрытые Blizzard, не может заблокировать ни один аддон."
L["Scanning auras - creating a list"] = "Сканирование аур - создание списка"
L["%d captured so far"] = "Записано: %d"
L["%d captured so far - %d hidden by Blizzard"] = "Записано: %d - скрыто Blizzard: %d"
L["Hidden auras are Blizzard-secret - no addon can block them. Everything blockable was captured."] = "Скрытые ауры - секреты Blizzard, ни один аддон не может их заблокировать. Всё, что можно заблокировать, записано."
L["Blocked by Blizzard during this fight - resumes automatically. In instances, use the curated presets."] = "Заблокировано Blizzard во время этого боя - возобновится автоматически. В подземельях используйте готовые наборы."
L["Blizzard is blocking aura scanning right now (encounter, Mythic+, or PvP match). Use the curated presets - they cover everything blockable in instanced content."] = "Blizzard сейчас блокирует сканирование аур (босс, эпохальный+ или PvP-матч). Используйте готовые наборы - они покрывают всё, что можно заблокировать в подземельях."
L["Scan complete: %d auras readable right now, %d captured this session. %d more are hidden by Blizzard and cannot be blocked by any addon."] = "Сканирование завершено: аур доступно сейчас: %d, записано за сессию: %d. Ещё %d скрыто Blizzard - ни один аддон не может их заблокировать."
L["Stop scan"] = "Стоп"
L["Block selected aura"] = "Заблокировать выбранную ауру"
L["Blocks the selected aura using the exact ID it carries right now."] = "Блокирует выбранную ауру по точному ID, который она использует сейчас."
L["No readable auras right now"] = "Сейчас нет читаемых аур"
L["Rescan"] = "Обновить"
L["Re-reads the auras on the current unit and adds everything it sees to this session's captured list - works in combat too. Shift-click clears the captured list."] = "Заново считывает ауры текущей цели и добавляет всё увиденное в список, записанный за эту сессию - работает и в бою. Shift + щелчок очищает записанный список."
L["%s - captured"] = "%s - записана"
L["Scan complete: %d auras readable right now, %d captured this session."] = "Сканирование завершено: аур доступно сейчас: %d, записано за сессию: %d."

-- Завершение полной локализации на основе исходников Menu2.
L["Aura settings are only available for Player, Target, Focus, and Boss Frames."] = "Настройки аур доступны только для фреймов игрока, цели, фокуса и босса."
L["Aura settings were skipped for unsupported UnitFrames."] = "Настройки аур пропущены для неподдерживаемых фреймов юнитов."
L["Back and Forward between pages"] = "Назад и Вперёд между страницами"
L["Back and Forward page history in the bottom-left menu bar"] = "история страниц Назад и Вперёд в левом нижнем углу строки меню"
L["Blizzard animated Zzz"] = "Анимированные Zzz Blizzard"
L["Bottom half"] = "Нижняя половина"
L["Castbar settings are only available for Player, Target, Focus, and Boss Frames."] = "Настройки полосы заклинаний доступны только для фреймов игрока, цели, фокуса и босса."
L["Castbar settings were skipped for UnitFrames without Castbars."] = "Настройки полосы заклинаний пропущены для фреймов юнитов без полосы заклинаний."
L["Changing this value selects Manual width. For Player, it also turns off Sync width to Class Resource so the new width takes effect immediately."] = "Изменение этого значения выбирает Ручную ширину. Для игрока также отключается синхронизация ширины с ресурсом класса, чтобы новая ширина применилась сразу."
L["Current target only"] = "Только текущая цель"
L["Edits the selected child element's local X offset. Positive values move right. Arrow keys and dragging update the same offset."] = "Изменяет локальное смещение X выбранного дочернего элемента. Положительные значения сдвигают его вправо. Клавиши со стрелками и перетаскивание изменяют то же смещение."
L["Edits the selected child element's local Y offset. Positive values move up. Arrow keys and dragging update the same offset."] = "Изменяет локальное смещение Y выбранного дочернего элемента. Положительные значения сдвигают его вверх. Клавиши со стрелками и перетаскивание изменяют то же смещение."
L["Exact X offset"] = "Точное смещение X"
L["Exact Y offset"] = "Точное смещение Y"
L["Full texture"] = "Полная текстура"
L["Height (0 = auto)"] = "Высота (0 = автоматически)"
L["Highlight texture"] = "Текстура выделения"
L["Jump between recent settings pages without finding them again in navigation or search."] = "Переходите между недавними страницами настроек, не разыскивая их снова в навигации или поиске."
L["New Back and Forward arrows in the bottom-left menu bar remember the pages you visit."] = "Новые стрелки Назад и Вперёд в левом нижнем углу строки меню запоминают посещённые страницы."
L["No copy categories selected."] = "Категории для копирования не выбраны."
L["Nothing was copied."] = "Ничего не скопировано."
L["Outline style"] = "Стиль контура"
L["Rounded frames ignore True Outline and Texture styles and keep the solid outline color."] = "Скруглённые фреймы игнорируют стили Настоящий контур и Текстура и сохраняют сплошной цвет контура."
L["Texture region"] = "Область текстуры"
L["Top half"] = "Верхняя половина"
L["True Outline"] = "Настоящий контур"
L["Try the Back button"] = "Попробовать кнопку Назад"
L["offset, size, and layer"] = "смещение, размер и слой"

L["Requires a UI reload."] = "Требуется перезагрузка интерфейса."
