L["No target"] = "Нет цели"
L["Out of combat and no target"] = "Вне боя и нет цели"

L["Class Resource Text"] = "Текст ресурса класса"
L["Click to select the value, then press Ctrl+C to copy it."] = "Щёлкните, чтобы выбрать значение, затем нажмите Ctrl+C для копирования."
L["HEX color"] = "Цвет HEX"
L["NSRT nickname integration"] = "Интеграция псевдонимов NSRT"
L["Nickname Integration"] = "Интеграция псевдонимов"
L["On (default): names supplied by Northern Sky Raid Tools replace character names on MSUF unit and group frames. Turn this off to always show character names in MSUF. NSRT and its settings are not modified."] = "Включено (по умолчанию): псевдонимы из Northern Sky Raid Tools заменяют имена персонажей на одиночных и групповых рамках MSUF. Отключите эту опцию, чтобы MSUF всегда показывал имена персонажей. NSRT и его настройки не изменяются."

-- Native 12.1 spell-ID tooltip CVar (Global > Misc > Unitframe tooltips).
L["Show spell IDs in aura tooltips"] = "Показывать ID заклинаний в подсказках аур"
L["Aura tooltip spell IDs"] = "ID заклинаний в подсказках аур"
L["On: aura tooltips show the numeric spell ID through the game's own 12.1 option, and MSUF re-enables that option after every login because the game forgets it between sessions. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "Вкл.: подсказки аур показывают числовой ID заклинания через собственную настройку игры 12.1, и MSUF заново включает её после каждого входа, потому что игра забывает её между сессиями. Выкл. (по умолчанию): MSUF никогда не трогает игровую настройку, так что другие аддоны или ручная настройка через консоль сохраняют контроль; выключение этого переключателя однократно отключает настройку."

-- Guided setup restart confirmation.
L["Run the guided setup again? The walkthrough starts over at the first step."] = "Запустить пошаговую настройку заново? Обучение начнётся с первого шага."
L["Dispel Type Colors"] = "Цвета типов рассеивания"
L["Magic custom"] = "Своя магия"
L["Magic color"] = "Цвет магии"
L["Curse custom"] = "Своё проклятие"
L["Curse color"] = "Цвет проклятия"
L["Disease custom"] = "Своя болезнь"
L["Disease color"] = "Цвет болезни"
L["Poison custom"] = "Свой яд"
L["Poison color"] = "Цвет яда"
L["Bleed custom"] = "Своё кровотечение"
L["Bleed color"] = "Цвет кровотечения"
L["Optional global overrides for harmful Magic, Curse, Disease, Poison and Bleed indicators. Off uses Blizzard's current default. The last edited type is shown first in every aura preview."] = "Необязательные общие цвета индикаторов вредоносных эффектов магии, проклятия, болезни, яда и кровотечения. При отключении используется текущий стандарт Blizzard. Последний изменённый тип показывается первым во всех предпросмотрах аур."
L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Цвета таймеров и рассеивания общие для активных аур юнитов и групп и всех предпросмотров. Цвета рамки и тени значка находятся в Оформление > Ауры и задаются по типу ауры."
L["Cooldown timer urgency, global Dispel types, icon borders and shadows."] = "Срочность таймеров, общие типы рассеивания, рамки и тени значков."
L["Safe, Warning, Urgent, Magic, Curse, Disease, Poison, Bleed, icon border and icon shadow."] = "Безопасно, Предупреждение, Срочно, Магия, Проклятие, Болезнь, Яд, Кровотечение, рамка и тень значка."
L["While unlocked, the Combat Enter/Leave text is shown permanently as a movable handle. Drag it with the mouse or nudge it with the arrow keys. Lock it so the text only appears when entering or leaving combat."] = "Пока позиция не заблокирована, текст входа/выхода из боя постоянно отображается как перемещаемый элемент. Перетащите его мышью или сдвигайте клавишами со стрелками. Заблокируйте позицию, чтобы текст появлялся только при входе в бой или выходе из него."
L["While unlocked, the Combat Timer stays visible out of combat as a movable 0:00 placeholder. Drag it with the mouse or nudge it with the arrow keys - with click-through enabled, hold ALT to drag. Lock it to freeze the position."] = "Пока позиция не заблокирована, таймер боя остаётся видимым вне боя в виде перемещаемой заглушки 0:00. Перетащите его мышью или сдвигайте клавишами со стрелками; при включённом сквозном клике удерживайте ALT для перетаскивания. Заблокируйте позицию, чтобы зафиксировать её."

L["Switched to profile '%s'.\n\nA UI reload is required to fully apply this profile.\n\nReload now?"] = "Выполнен переход к профилю «%s».\n\nДля полного применения этого профиля требуется перезагрузка интерфейса.\n\nПерезагрузить сейчас?"
L["Switched to profile '%s'. Reload after combat with /reload."] = "Выполнен переход к профилю «%s». После боя выполните /reload."
L["Switched to profile '%s'. Reload the UI with /reload."] = "Выполнен переход к профилю «%s». Перезагрузите интерфейс командой /reload."
L["Can't reload the UI in combat. Leave combat, then type /reload."] = "Нельзя перезагрузить интерфейс в бою. Выйдите из боя и введите /reload."

L["Buff Reminder"] = "Напоминание об усилении"
L["Show placeholders for missing auras"] = "Показывать заполнители для отсутствующих аур"
L["Gives every whitelisted spell its own fixed slot and draws a dimmed icon underneath it. A running aura covers its own placeholder, so a dimmed icon means that spell is missing. MSUF reads no aura data for this, so it keeps working in raids, Mythic+ and arenas. Reminder slots ignore this container's sorting and duration bars."] = "Каждое заклинание из белого списка получает собственную фиксированную ячейку, под которой рисуется приглушённый значок. Действующая аура закрывает свой заполнитель, поэтому приглушённый значок означает, что это заклинание отсутствует. MSUF не читает для этого данные аур, поэтому функция работает и в рейдах, Мифическом+ и на аренах. Ячейки напоминания игнорируют сортировку и полосы длительности этого контейнера."
L["Placeholder opacity"] = "Непрозрачность заполнителя"
L["How strongly a missing aura's placeholder is drawn. Lower values keep the frame calm; the running aura always covers it completely either way."] = "Насколько ярко рисуется заполнитель отсутствующей ауры. Низкие значения делают рамку спокойнее; действующая аура в любом случае полностью его закрывает."
L["Grey out placeholders"] = "Обесцвечивать заполнители"
L["Draws the placeholder without colour so a missing aura reads at a glance. Turn this off to keep the spell's own colours and separate the two states by opacity or tint alone."] = "Рисует заполнитель без цвета, чтобы отсутствующая аура была заметна сразу. Отключите, чтобы сохранить собственные цвета заклинания и различать состояния только по непрозрачности или оттенку."
L["Placeholder tint"] = "Оттенок заполнителя"
L["%d fixed reminder slots · whitelist order decides their position."] = "Фиксированных ячеек напоминания: %d · порядок белого списка определяет их положение."
L["Off · this container shows only auras that are currently active."] = "Выключено · этот контейнер показывает только активные сейчас ауры."
L["Reminder on"] = "Напоминание вкл."
L["Reminder off"] = "Напоминание выкл."
L["Click the icon to cast the spell"] = "Щёлкните по значку, чтобы применить заклинание"
L["Turns every reminder slot into a cast button: clicking it casts that slot's spell at this frame's unit, whether the aura is missing or already running, so re-applying a poison or flask works. The binding is written once outside combat and never changes afterwards, so this costs no timer, no event and no aura read. Only spells work; food, flasks and other items cannot be triggered this way."] = "Превращает каждую ячейку напоминания в кнопку применения: щелчок применяет заклинание этой ячейки к единице этой рамки — независимо от того, отсутствует ли аура или уже действует, так что повторное нанесение яда или флакона тоже работает. Привязка записывается один раз вне боя и больше не меняется, поэтому не стоит ни таймера, ни события, ни чтения аур. Работают только заклинания; еду, флаконы и другие предметы так запустить нельзя."
L["Click-cast"] = "Клик-применение"
L["Remind me about the Main Hand"] = "Напоминать о правой руке"
L["Adds a slot that watches the temporary enchant on your main hand - a weapon oil, a stone or a weapon-applied poison. Unlike an aura this state is plainly readable, so the icon lights up while the enchant runs and dims when it is gone, in every kind of content."] = "Добавляет ячейку, которая следит за временным чародейством на оружии в правой руке: масло, камень или нанесённый на оружие яд. В отличие от ауры это состояние читается напрямую, поэтому значок горит, пока чародейство действует, и тускнеет, когда оно заканчивается — в любом контенте."
L["Remind me about the Off Hand"] = "Напоминать о левой руке"
L["Same slot for your off hand. Both hands share the consumable configured below, which is what you normally want."] = "Такая же ячейка для левой руки. Обе руки используют один и тот же расходуемый предмет, указанный ниже — обычно именно это и нужно."
L["Oil or stone - item link or ID"] = "Масло или камень — ссылка на предмет или ID"
L["Use this item"] = "Использовать этот предмет"
L["Oil or stone"] = "Масло или камень"
L["Paste the consumable you want the slot to offer on click. Leave it empty to keep the reminder as a pure indicator. Weapon enchants cannot be cast, so only an item makes these slots clickable."] = "Вставьте расходуемый предмет, который ячейка должна предлагать по щелчку. Оставьте пустым, чтобы напоминание оставалось только индикатором. Чародейства на оружие нельзя применить как заклинание, поэтому кликабельными эти ячейки делает только предмет."
L["Click uses %s."] = "Клик использует %s."
L["No item set · the enchant slots only indicate."] = "Предмет не задан · ячейки чародейства только показывают."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs. Paste an item link instead to track the buff that item applies and offer the item itself on click - flasks, runes, stones and potions all work that way. If the item's buff differs from its use effect, put both on one line: the Spell ID decides what is tracked, the item what a click uses."] = "Введите ID заклинания, вставьте ссылку на заклинание или наберите его название. Список отслеживает точные ID заклинаний. Вместо этого вставьте ссылку на предмет, чтобы отслеживать даваемый им эффект и предлагать сам предмет по щелчку: флаконы, руны, камни и зелья работают именно так. Если эффект предмета отличается от его действия при использовании, укажите оба в одной строке: ID заклинания решает, что отслеживается, а предмет — что использует щелчок."
L["Click uses this item"] = "Клик использует этот предмет"
L["Click casts this"] = "Клик применяет это"
L["No click action · paste an item"] = "Нет действия по клику · вставьте предмет"
L["%d of %d slots can be clicked."] = "Нажать можно на %d из %d ячеек."
L["Only active auras"] = "Только активные ауры"
L["Fixed slots (reminder)"] = "Фиксированные ячейки (напоминание)"
L["Display"] = "Отображение"
L["Every whitelisted entry keeps its own place. A dimmed icon means that entry is missing."] = "Каждая запись белого списка сохраняет своё место. Приглушённый значок означает, что этой записи нет."
L["Only auras that are currently active are shown, packed together."] = "Показываются только активные сейчас ауры, сжато."
L["Sorting is off while this container shows fixed reminder slots · their order comes from the Whitelist."] = "Сортировка отключена, пока контейнер показывает фиксированные ячейки напоминания · их порядок берётся из белого списка."
L["Reminder slots do not draw a duration bar."] = "Ячейки напоминания не рисуют полосу длительности."
L["Unavailable"] = "Недоступно"
L["Off · switch Display to Fixed slots in Setup to use this."] = "Выключено · переключите Отображение на Фиксированные ячейки в Setup."
L["%d fixed slots · order comes from the Whitelist."] = "Фиксированных ячеек: %d · порядок из белого списка."
L["%d fixed slots · %d clickable · order comes from the Whitelist."] = "Фиксированных ячеек: %d · нажимаемых: %d · порядок из белого списка."
L["Add a buff - Spell ID, spell link or item link"] = "Добавить усиление – ID заклинания, ссылка на заклинание или предмет"
L["Add a debuff - Spell ID, spell link or item link"] = "Добавить ослабление – ID заклинания, ссылка на заклинание или предмет"
L["Weapon enchants"] = "Чародейства на оружие"
L["Track the Main Hand enchant"] = "Отслеживать чародейство правой руки"
L["Adds a reminder slot for the temporary enchant on your main hand - a weapon oil, a stone or a weapon-applied poison. Unlike an aura this state is plainly readable, so the icon lights up while the enchant runs and dims when it is gone, in every kind of content."] = "Добавляет ячейку напоминания для временного чародейства на оружии в правой руке: масло, камень или нанесённый на оружие яд. В отличие от ауры это состояние читается напрямую, поэтому значок горит, пока чародейство действует, и тускнеет, когда оно заканчивается — в любом контенте."
L["Track the Off Hand enchant"] = "Отслеживать чародейство левой руки"
L["Same slot for your off hand. Both hands share the consumable set below, which is what you normally want."] = "Такая же ячейка для левой руки. Обе руки используют один и тот же расходуемый предмет, указанный ниже — обычно именно это и нужно."
L["Bind item"] = "Привязать предмет"
L["Paste the consumable these slots should offer on click. A weapon enchant cannot be cast, so only an item makes them clickable. Leave it empty to keep them as pure indicators."] = "Вставьте расходуемый предмет, который эти ячейки должны предлагать по щелчку. Чародейство на оружие нельзя применить как заклинание, поэтому кликабельными их делает только предмет. Оставьте пустым, чтобы они оставались только индикаторами."
L["Needs Display set to Fixed slots in Setup · enchants have no aura to show otherwise."] = "Требует Отображение = Фиксированные ячейки в Setup · иначе чародействам нечего показывать."
L["No weapon slot tracked."] = "Ни одна ячейка оружия не отслеживается."
L["No item bound · these slots only indicate."] = "Предмет не привязан · эти ячейки только показывают."
L["%d tracked"] = "Отслеживается: %d"
L["Only show what I can apply myself"] = "Показывать только то, что я могу применить сам"
L["Hides every whitelisted spell this character cannot cast, without leaving a gap. One whitelist can then serve all your characters: the Mage keeps Arcane Intellect, the Rogue keeps the poisons. Rows with a bound item always stay, because an item is not class bound. MSUF re-checks this only when your spellbook or talents actually change, never during combat."] = "Скрывает каждое заклинание из белого списка, которое этот персонаж не может применить, не оставляя пустоты. Один белый список подходит всем вашим персонажам: маг сохраняет «Чародейский разум», разбойник — яды. Строки с привязанным предметом остаются всегда, ведь предмет не привязан к классу. MSUF перепроверяет это только при реальном изменении книги заклинаний или талантов и никогда в бою."
L["%d hidden: not castable by this character."] = "Скрыто: %d — этот персонаж их не применяет."
L["Always show"] = "Всегда показывать"
L["Pins this entry so the self-cast filter never hides it. Use it for anything that is not a class ability - a flask, food, a rune, a buff someone else casts on you. MSUF cannot tell those apart from another class's spell on its own: nothing reports which class owns a Spell ID."] = "Закрепляет запись, чтобы фильтр никогда её не скрывал. Используйте для всего, что не является классовой способностью: флакон, еда, руна или баф, который даёт вам кто-то другой. MSUF не отличает их от чужого классового заклинания: ничто не сообщает, какому классу принадлежит ID заклинания."
L["Filter again"] = "Снова фильтровать"
L["Lets the self-cast filter decide about this entry again. It will be hidden on characters that cannot cast it."] = "Возвращает запись фильтру. На персонажах, которые не могут её применить, она будет скрыта."
L["always shown"] = "всегда видна"
L["hidden on this character"] = "скрыто на этом персонаже"
L["Hides every whitelisted spell this character cannot cast, without leaving a gap. One whitelist can then serve all your characters: the Mage keeps Arcane Intellect, the Rogue keeps the poisons. Nothing reports which class owns a Spell ID, so a flask buff looks exactly like a foreign class ability here - protect those with a bound item, or with Always show on the row in the Whitelist. MSUF re-checks this only when your spellbook or talents actually change, never during combat."] = "Скрывает каждое заклинание из белого списка, которое этот персонаж не может применить, не оставляя пустоты. Один белый список подходит всем персонажам: маг сохраняет «Чародейский разум», разбойник — яды. Ничто не сообщает, какому классу принадлежит ID заклинания, поэтому баф от флакона выглядит так же, как чужое классовое заклинание — защитите такие записи привязанным предметом или кнопкой «Всегда показывать». MSUF перепроверяет это только при реальном изменении книги заклинаний или талантов и никогда в бою."

--- Arena frames (dedicated arena1-3 unit frames)
L["Arena"] = "Арена"
L["Arena Castbar"] = "Полоса заклинаний арены"
L["Arena Frames"] = "Фреймы арены"
L["Arena Layout"] = "Расположение арены"
L["Arena Opponent"] = "Соперник на арене"
L["Arena castbar preview"] = "Предпросмотр полосы заклинаний арены"
L["Arena frame layout"] = "Расположение фреймов арены"
L["Arena spacing"] = "Интервал арены"
L["Aura settings are only available for Player, Target, Focus, Boss, and Arena Frames."] = "Настройки аур доступны только для фреймов игрока, цели, фокуса, босса и арены."
L["Castbar settings are only available for Player, Target, Focus, Boss, and Arena Frames."] = "Настройки полосы заклинаний доступны только для фреймов игрока, цели, фокуса, босса и арены."
L["MSUF Arena Frames"] = "MSUF Фреймы арены"
L["Sort roles across entire raid"] = "Сортировать роли по всему рейду"
L["Orders tanks, healers, and damage dealers across the whole raid instead of within each raid group. Raid and Mythic Raid only: applies to By Role together with Preserve raid groups, and to Group + Role."] = "Упорядочивает танков, лекарей и бойцов по всему рейду, а не внутри каждой рейдовой группы. Только для рейда и эпохального рейда: действует для сортировки по роли вместе с сохранением рейдовых групп, а также для режима Группа + Роль."
L["Raid-wide roles"] = "Роли по всему рейду"

-- Dispel border unit filter.
L["Show on"] = "Показывать для"
L["Friendly"] = "Дружественные"
L["Enemy"] = "Враждебные"
L["Both"] = "Все"
-- Menu feature localization: resource displays, mouseover fades, markers and textures.
L[" - clear Search to reorder"] = " — очистить поиск для изменения порядка"
L[" - drag to set Custom Priority"] = " — перетащите, чтобы установить собственный приоритет."
L[" - dynamic priority active"] = " - активен динамический приоритет"
L["%d tracked DoTs"] = "Отслеживаемых DoT: %d"
L["85% above 15 members / 70% above 25"] = "85% при числе участников более 15 / 70% при числе более 25"
L["Active: %s"] = "Активен: %s"
L["Active: Always"] = "Активно: Всегда"
L["Advanced texture options"] = "Расширенные параметры текстуры"
L["All selected visibility conditions must match (AND)."] = "Все выбранные условия видимости должны выполняться одновременно (И)."
L["Applies the built-in additive highlight style to this texture slot."] = "Применяет встроенный аддитивный стиль подсветки к этому слоту текстуры."
L["Arms only. Shows actual aura charges in a segmented bar, using the same native display as Fury Whirlwind. These two trackers use a bar with static dividers; aura values are never read by the addon. Appearance changes during combat apply after combat."] = "Только специализация «Оружие». Показывает фактические заряды ауры на сегментированной полосе с тем же встроенным отображением, что и «Вихрь» для «Неистовства». Оба индикатора используют полосу с неподвижными разделителями; аддон не считывает значения ауры. Изменения оформления, сделанные в бою, применяются после боя."
L["Arrow"] = "Стрелка"
L["Arrow direction"] = "Направление стрелки"
L["Augmentation Evoker only. The Player power bar shows the remaining Ebon Might duration instead of Mana, and uses the Player Power settings below for width, height, position, textures and text. Essence stays an ordinary Class Resource, and Mana is available through Alternative Mana. Turn this off to get a normal Mana bar back."] = "Только пробудитель специализации «Насыщатель». Полоса ресурса игрока показывает оставшееся время «Черной мощи» вместо маны. Ширина, высота, положение, текстуры и текст задаются настройками ресурса игрока ниже. Сущность остается обычным ресурсом класса, а мана доступна через альтернативную полосу маны. Отключите, чтобы вернуть обычную полосу маны."
L["Aura Options, Ordering and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Auras."] = "Параметры ауры, порядок расположения и стиль ауры принадлежат этому рамке юнита. Общий внешний вид значков: Внешний вид > Ауры."
L["Aura Preview Zoom"] = "Увеличение предварительного просмотра ауры"
L["Auto fit pips is active only for Circle, Diamond and Hex. It uses pip count x pip size plus gaps."] = "Автоподбор точек активен только для круга, ромба и шестигранника. Он использует количество пунктов x размер пунктов плюс промежутки."
L["Automatic preserves the current profile behavior for the active class and specialization, including Maelstrom, Insanity, and Ebon Might hand-offs. Mana explicitly keeps Mana on the Player power bar. Vehicles always use their native resource; classes without a Mana pool keep their normal resource while the preference stays saved."] = "Автоматический режим сохраняет поведение текущего профиля для активных класса и специализации, включая переходы к Водовороту, Безумию и Черной мощи. Режим «Мана» явно оставляет ману на полосе ресурса игрока. Транспорт всегда использует свой ресурс; классы без маны сохраняют обычный ресурс, а выбранная настройка остается сохраненной."
L["BG opacity"] = "Непрозрачность фона"
L["Bar height (0 = full)"] = "Высота полосы (0 = полная)"
L["Basic setup"] = "Базовая настройка"
