L["Shows the selected dragon on this unit's visible portrait. Off restores the real classification. Ends when this area closes or combat starts."] = "Показывает выбранного дракона на видимом портрете этой цели. Отключение восстанавливает реальную классификацию. Просмотр завершается при выходе из раздела или начале боя."
L["Color above threshold"] = "Цвет при здоровье выше порога"
L["Color and opacity are in Appearance > Colors > Group Frame Colors."] = "Цвет и непрозрачность находятся в разделе «Внешний вид» > «Цвета» > «Цвета групповой рамки»."
L["Color by class applies to all unit power bars. Resource colors apply when it is off. A matched background follows Health."] = "Цвет класса применяется ко всем полосам ресурса юнитов. При отключении используются цвета ресурсов. Согласованный фон следует за здоровьем."
L["Colors follow the currently selected preview resource."] = "Цвета соответствуют ресурсу, выбранному в предпросмотре."
L["Combat state"] = "Боевое состояние"
L["Creates a simple monochrome texture on the health bar. You can then choose any bar texture and place HP text above it."] = "Создает простую монохромную текстуру на шкале здоровья. Затем вы можете выбрать любую текстуру полосы и разместить над ней текст HP."
