L["For Bar, the first direction controls the fill: Right fills left-to-right; Left fills right-to-left. Up or Down remains the secondary layout direction."] = "Для панели первое направление управляет заливкой: «Справа» заполняется слева направо; Слева заполняется справа налево. Вверх или вниз остается второстепенным направлением макета."
