L["Hover the unit frame to reveal this text. Preview stays visible. 0 seconds = instant."] = "Наведите курсор на рамку объекта, чтобы отобразить этот текст. Предварительный просмотр остается видимым. 0 секунд = мгновенно."
L["In Bear Form, replaces the empty Guardian class-resource slot with an estimated Ironfur lifetime bar. Each successful cast adds one moving marker; Ursoc's Endurance and Guardian of Elune are included."] = "В облике медведя заменяет пустую область ресурса «Стража» полосой с оценкой оставшегося времени «Железного меха». Каждое успешное применение добавляет движущуюся метку; учитываются «Выносливость Урсока» и «Страж Элуны»."
L["Ironfur Cast Markers"] = "Метки применения железного меха"
L["Keep Absorbs + Prediction Visible"] = "Оставлять поглощение и прогноз лечения видимыми"
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Auras owns only the global icon theme."] = "Расположение, фильтры, списки и индивидуальный стиль контейнеров настраиваются в каждом фрейме. Внешний вид > Ауры управляет только общей темой значков."
