L["Open Frames > Party/Raid Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Откройте Рамки > Рамки группы/рейда > Ауры для фильтров положительных и отрицательных эффектов, списков, видимости и расположения. Для текста, восстановления, стаков и полос длительности откройте Внешний вид > Ауры и выберите Группу или Рейд."
L["Open Frames > Party/Raid Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Appearance > Bars > Absorb Display."] = "Откройте Рамки > Рамки группы/рейда > Расположение. Текст, Полоса ресурса и Затухание по расстоянию находятся рядом с основными настройками и прозрачностью. Наложение рассеивания и Полоса отрицательного эффекта находятся на странице Наложение рассеивания. Прогноз лечения находится в разделе Внешний вид > Полосы > Отображение поглощения."
L["Opens: Frames > Party/Raid Frames > Layout"] = "Открывается: Рамки > Рамки группы/рейда > Макет."
L["Opens: Frames > Party/Raid Frames > Status & Indicators"] = "Открывается: Рамки > Рамки группы/рейда > Статус и индикаторы."
L["Options:"] = "Опции:"
L["Orb size"] = "Размер сферы"
L["Ordering and individual Style are edited here. Global icon theme: Appearance > Auras."] = "Здесь редактируются порядок и индивидуальный стиль. Глобальная тема значков: «Внешний вид» > «Ауры»."
L["Pandemic only"] = "Только окно Pandemic"
L["Performance warning\n\nCustom Boss update rates replace the adaptive default with continuous range checks for every visible Boss Frame. Higher values can increase CPU use during encounters.\n\nStandard keeps the performance-friendly adaptive rate."] = "Предупреждение о производительности\n\nПользовательская частота обновления боссов заменяет адаптивное значение постоянными проверками расстояния для каждой видимой рамки босса. Более высокие значения могут увеличить нагрузку на CPU во время сражений.\n\nСтандарт сохраняет экономную адаптивную частоту."
L["Player Power layer"] = "Слой ресурса игрока"
L["Player Power text layer"] = "Слой текста ресурса игрока"
L["Power Loss Color"] = "Цвет потери ресурса"
L["Power X"] = "Ресурс X"
L["Power Y"] = "Ресурс Y"
L["Power bar color by class"] = "Цвет полосы ресурса по классу"
L["Power loss glow"] = "Свечение при потере ресурса"
L["Power text size"] = "Размер текста ресурса"
L["Quick setup"] = "Быстрая настройка"
L["Raises this DoT in the fixed priority order."] = "Повышает этот DoT в порядке фиксированного приоритета."
L["Remove DoT"] = "Удалить DoT"
L["Requires MapkoSkin API 2.1. Disabling restores the MSUF look; unit frames and profile colors are unchanged."] = "Требуется MapkoSkin API 2.1. Отключение возвращает оформление MSUF; рамки юнитов и цвета профиля не меняются."
L["Resource text"] = "Текст ресурса"
L["Shape, border and shadow: Appearance > Auras > Buffs. All controls here remain Group-scope aware."] = "Форма, граница и тень: Внешний вид > Ауры > Усиления. Все элементы управления здесь остаются осведомленными о групповой области."
L["Shared Dispel type colors plus the other colors available to this card's border modes."] = "Общие цвета типов рассеивания и другие цвета, доступные для режимов границы этой карточки."
L["Shared by Dispel borders, overlays, symbols, and every related preview."] = "Общий цвет для границ, наложений и символов рассеивания, а также всех связанных предпросмотров."
L["Show Ebon Might duration (Aug)"] = "Показывать длительность черной мощи (Насыщатель)"
L["Show Ironfur cast markers"] = "Показывать метки применения железного меха"
L["Show Ironfur tracker (Guardian)"] = "Показывать отслеживание железного меха (Страж)"
