L["Show negative heal absorbs"] = "Показывать поглощение лечения"
L["Show only below 100% health"] = "Показывать только здоровье ниже 100%."
L["Show positive absorbs"] = "Показывать поглощение урона"
L["Shows one moving marker per tracked Ironfur cast. The 30 Hz motion ticker exists only while the optional tracker has active casts."] = "Показывает движущуюся метку для каждого отслеживаемого применения «Железного меха». Таймер движения с частотой 30 Гц работает только пока дополнительный индикатор отслеживает активные применения."
L["Single color uses this layer's configured tint. HP gradient follows the shared low, mid and high HP colors."] = "Один цвет использует настроенный оттенок этого слоя. Градиент HP соответствует общим низким, средним и высоким цветам HP."
L["Single marker"] = "Одиночный маркер"
L["Slug uses WoW's crisp vector font renderer. Slug supports None or normal Outline; Thick Outline and text shadow are unavailable while it is active."] = "Slug использует четкое векторное отображение шрифтов WoW. Поддерживаются варианты «Нет» и обычный контур; толстый контур и тень текста недоступны при активном Slug."
L["Soft gradient gives the whole frame a clear, portrait-safe hover cue. Solid border keeps a crisp edge. Choose its color in Appearance > Colors > Unit Frames."] = "Мягкий градиент четко подсвечивает всю рамку при наведении, не закрывая портрет. Сплошная граница сохраняет четкий край. Цвет выбирается в разделе Внешний вид > Цвета > Рамки юнитов."
L["Standard keeps the adaptive 0.75 / 2 second checks. Higher values continuously check visible Boss Frames at the selected rate; 20 per second is a 50 ms interval."] = "Стандартно сохраняются адаптивные проверки 0,75/2 секунды. При более высоких значениях видимые кадры боссов постоянно проверяются с выбранной скоростью; 20 в секунду — это интервал 50 мс."
L["Status icon controls include the Level indicator, visibility, anchor, size, and layer. Position is edited in Preview."] = "Настройки значков состояния включают индикатор уровня, видимость, привязку, размер и слой. Положение редактируется в предпросмотре."
