L["Triple arrow"] = "Тройная стрелка"
L["Updates per second"] = "Обновлений в секунду"
L["Use Appearance > Bars for highlight borders and Frames > Party/Raid Frames > Status & Indicators for role, threat, dispel, corner, and raid-marker indicators. Spell Indicators are in Frames > Party/Raid Frames > Auras."] = "Используйте «Внешний вид» > «Полосы» для выделения границ, а «Кадры» > «Рамки группы/рейда» > «Статус и индикаторы» для индикаторов роли, угрозы, рассеивания, угла и маркера рейда. Индикаторы заклинаний находятся в разделе «Рамки» > «Рамки группы/рейда» > «Ауры»."
L["Use global bar texture"] = "Использовать глобальную текстуру полосы"
L["Uses Blizzard's native StatusBar interpolation when an active aura duration is refreshed. The countdown itself remains C-side."] = "Использует собственную интерполяцию Blizzard StatusBar, когда обновляется продолжительность активной ауры. Сам обратный отсчет остается на стороне C."
L["Uses a separate texture opacity below the HP threshold. The normal Opacity from Setup remains active above it."] = "Использует отдельную непрозрачность текстуры ниже порога HP. Обычная непрозрачность из настроек остается активной над ним."
