L["Hard filter: when enabled (and filters are enabled), only debuffs in Blizzard's curated IMPORTANT list will be shown (e.g. raid mechanics, key defensives, etc.)."] = "Жёсткий фильтр: если включён (и фильтры активны), показываются только дебаффы из отобранного Blizzard списка ВАЖНОЕ (например, рейдовые механики, ключевые защитные умения и т. п.)."
L["Heal-Absorb Bar Color"] = "Цвет полосы поглощения исцеления"
L["Hearthstone, Reincarnation cooldown auras."] = "Ауры перезарядки камня возвращения и перевоплощения."
L["Height:"] = "Высота:"
L["Hidden. Click Show to reveal slash commands + power tools."] = "Скрыто. Нажмите «Показать», чтобы открыть слэш-команды и продвинутые инструменты."
L["Hide Blizzard PlayerFrame (Turn off for other addon compatibility)"] = "Скрыть фрейм игрока Blizzard (отключите для совместимости с другими аддонами)"
L["Hides Masque skin border/backdrop for Auras 2.0 icons (keeps icon + cooldown styling)."] = "Скрывает рамку и подложку скина Masque у значков «Аур 2.0» (оформление значка и перезарядки сохраняется)."
L["Hides buffs with no duration. Debuffs are never hidden by this option.\n\nNote: Target/Focus APIs may still show permanent buffs during combat due to API limitations."] = "Скрывает баффы без длительности. Дебаффы этой опцией никогда не скрываются.\n\nПримечание: из-за ограничений API интерфейсы цели и фокуса в бою могут по-прежнему показывать постоянные баффы."
L["Hides buffs with no duration. Debuffs are never hidden by this option.\n\nThis filter is applied out of combat only. Target/Focus APIs may still show permanent buffs during combat due to API limitations."] = "Скрывает баффы без длительности. Дебаффы этой опцией никогда не скрываются.\n\nФильтр действует только вне боя. Из-за ограничений API интерфейсы цели и фокуса в бою могут по-прежнему показывать постоянные баффы."
L["Highlights your own buffs with a border color (visual only; does not filter)."] = "Подсвечивает ваши собственные баффы цветом границы (только визуально, без фильтрации)."
L["Highlights your own debuffs with a border color (visual only; does not filter)."] = "Подсвечивает ваши собственные дебаффы цветом границы (только визуально, без фильтрации)."
