L["Mark of the Wild, Fortitude, Arcane Intellect, Battle Shout, etc."] = "Знак дикой природы, стойкость, чародейский интеллект, боевой клич и т. д."
L["Masque is not loaded/ready. Enable/load the Masque addon, then /reload."] = "Masque не загружен или не готов. Включите либо загрузите аддон Masque, затем выполните /reload."
L["Master for all filtering for the selected profile (Shared or a per-unit override). When off, no filtering/highlight is applied."] = "Главный переключатель всей фильтрации выбранного профиля (общей или переопределённой для юнита). Когда он выключен, фильтрация и подсветка не применяются."
L["Master toggle. When off, no auras are shown for Target/Focus/Boss."] = "Главный переключатель. Когда он выключен, ауры для цели, фокуса и боссов не показываются."
