L["Mythic+ only (party). Optional MSUF sync via addon messages. Disabled in raid/open world (0 overhead)."] = "Только «Мифик+» (группа). Необязательная синхронизация MSUF через сообщения аддонов. В рейде и открытом мире отключено (без нагрузки)."
