L["On: HP stays transparent and missing health uses the HP track color. Off: normal background transparency is used."] = "Вкл.: полоса здоровья остаётся прозрачной, а недостающее здоровье использует цвет дорожки здоровья. Выкл.: используется обычная прозрачность фона."
