L["Optional MSUF modules and UI styling (MSUF only)."] = "Дополнительные модули MSUF и оформление интерфейса (только MSUF)."
L["Optional: forces the Player castbar to use Class or Custom color during normal casts. Interrupt feedback still uses 'Interrupt color (all castbars)'."] = "Необязательно: заставляет полосу произнесения игрока использовать цвет класса или свой цвет при обычных заклинаниях. Отклик на прерывание по-прежнему использует «Цвет прерывания (все полосы)»."
