L["Party Interrupt Tracker\n\nThis is a BEST-GUESS tracker:\n• Detects PARTY interrupts via UNIT_SPELLCAST_SUCCEEDED.\n• Cooldowns are estimated from a static table (talents/resets may differ).\n• Some abilities/modifiers cannot be inspected reliably in 12.0.\n\nIf other party members also use MSUF, kicks are synced via addon messages to improve reliability.\n\nMythic+ only (party). Disabled in raid/open world."] = "Трекер прерываний группы\n\nЭто трекер на основе оценок:\n• Определяет прерывания членов группы через UNIT_SPELLCAST_SUCCEEDED.\n• Перезарядки оцениваются по фиксированной таблице (таланты и сбросы могут отличаться).\n• Некоторые способности и модификаторы в 12.0 нельзя проверить надёжно.\n\nЕсли другие члены группы тоже используют MSUF, прерывания синхронизируются через сообщения аддонов для большей точности.\n\nТолько «Мифик+» (группа). В рейде и открытом мире отключено."
