L["Shows stack/application counts (e.g. \"2\") on aura icons. Disable to hide stack numbers."] = "Показывает количество стаков (например, «2») на значках аур. Отключите, чтобы скрыть числа."
L["Shows the countdown numbers on aura icons. Disable to hide cooldown numbers (swipe can remain enabled)."] = "Показывает числа обратного отсчёта на значках аур. Отключите, чтобы скрыть их (заливка перезарядки может остаться включённой)."
