L["TIP: Hover this slider and use the Mouse Wheel to change the scale in 5% steps.\n\nScales only MSUF frames (unitframes + castbars). Range 25%–150% (0.25–1.50). Drag or click to adjust. Applied immediately; in combat it applies after combat."] = "СОВЕТ: наведите курсор на этот ползунок и крутите колесо мыши, чтобы менять масштаб шагами по 5 %.\n\nМасштабирует только фреймы MSUF (фреймы юнитов и полосы произнесения). Диапазон 25 %–150 % (0,25–1,50). Перетаскивайте или щёлкайте для настройки. Применяется сразу; в бою — после его окончания."
L["TIP: Hover this slider and use the Mouse Wheel to change the scale in 5% steps.\n\nScales only the MSUF Slash Menu window. Range 25%–150% (0.25–1.50). Drag or click to adjust. Applied immediately."] = "СОВЕТ: наведите курсор на этот ползунок и крутите колесо мыши, чтобы менять масштаб шагами по 5 %.\n\nМасштабирует только окно меню MSUF. Диапазон 25 %–150 % (0,25–1,50). Перетаскивайте или щёлкайте для настройки. Применяется сразу."
