L["Tints the health bar when a dispellable debuff is active. Works alongside the highlight border.\nColors are shared with |cffffd200Global Style > Colors|r > |cffffd200Dispel|r."] = "Окрашивает полосу здоровья, когда активен рассеиваемый дебафф. Работает вместе с границей подсветки.\nЦвета общие с |cffffd200Глобальный стиль > Цвета|r > |cffffd200Рассеивание|r."
L["Tip of the Spear (SV)"] = "Остриё копья (Выживание)"
L["Tip:"] = "Совет:"
L["Tip: /msuf opens the menu."] = "Совет: команда /msuf открывает меню."
L["Tip: Hold SHIFT (5) / CTRL (10) / ALT (grid step) for bigger steps."] = "Совет: удерживайте SHIFT (5) / CTRL (10) / ALT (шаг сетки) для большего шага."
L["Tip: Move the preview via mousedrag"] = "Совет: перемещайте предпросмотр перетаскиванием мышью"
L["ToT Load Conditions"] = "Условия загрузки цели цели"
L["Toggle MSUF Edit Mode (only affects Midnight Simple Unit Frames)."] = "Переключает режим редактирования MSUF (затрагивает только Midnight Simple Unit Frames)."
L["Track interrupts on your Focus without showing the Focus castbar."] = "Отслеживайте прерывания у фокуса, не показывая его полосу произнесения."
L["Troubleshoot: If visuals don’t update, a quick |cff00ff00/reload|r fixes most UI state issues."] = "Устранение неполадок: если оформление не обновляется, быстрый |cff00ff00/reload|r решает большинство проблем состояния интерфейса."
L["Try a page name like bars, profiles, auras, castbar, colors, group, or target."] = "Попробуйте название страницы: полосы, профили, ауры, полоса произнесения, цвета, группа или цель."
L["Turned Off in Gameplay"] = "Отключено в разделе «Игровой процесс»"
L["Turns off Override shared filters and caps for all units and reverts them to Shared."] = "Отключает «Переопределить общие фильтры» и ограничения для всех юнитов и возвращает их к общим настройкам."
L["Turns off all scaling MSUF applies (global UI scale + MSUF-only scale), then reloads your UI. Blizzard handles scaling."] = "Отключает всё масштабирование, применяемое MSUF (глобальный масштаб интерфейса и собственный масштаб MSUF), и перезагружает интерфейс. Дальше масштабированием занимается Blizzard."
L["Type"] = "Тип"
L["UI scale tip: MSUF has its own UI scale — separate from the Global UI scale."] = "Совет по масштабу: у MSUF есть собственный масштаб интерфейса, независимый от глобального."
L["Undo last change"] = "Отменить последнее изменение"
L["Unified bar color"] = "Единый цвет полосы"
L["Unitframe"] = "Фрейм юнита"
L["Update text every event (higher CPU, pixel-accurate)"] = "Обновлять текст при каждом событии (выше нагрузка на ЦП, точность до пикселя)"
L["Updates the power number on every game event"] = "Обновляет число ресурса при каждом игровом событии"
L["Use \"Enable filters\" in the Auras 2.0 box as the master switch.\n\nInclude toggles are additive (they never hide your normal auras).\nHighlight toggles only change border colors.\n\nDebuff types: if you select ANY type, debuffs are limited to the selected types."] = "Используйте «Включить фильтры» в блоке «Ауры 2.0» как главный переключатель.\n\nПереключатели включения работают дополняюще (они никогда не скрывают ваши обычные ауры).\nПереключатели подсветки меняют только цвета границ.\n\nТипы дебаффов: если выбрать ЛЮБОЙ тип, дебаффы ограничиваются выбранными типами."
L["Use Midnight style icons"] = "Использовать значки в стиле Midnight"
L["Use bold text (THICKOUTLINE)"] = "Использовать жирный текст (THICKOUTLINE)"
L["Use global background texture"] = "Использовать глобальную текстуру фона"
L["Use the Bar settings scope dropdown (left panel, bottom) to choose which unit these settings apply to."] = "Выберите юнита, к которому применяются эти настройки, в выпадающем списке области действия полосы (левая панель, внизу)."
L["Use the Bar settings scope dropdown to choose which unit these settings apply to."] = "Выберите юнита, к которому применяются эти настройки, в выпадающем списке области действия полосы."
L["Used by: Crosshair color"] = "Используется для: цвет прицела"
L["Useful for positioning/offset testing."] = "Удобно для проверки положения и смещения."
L["Uses ExponentialEaseOut interpolation on the"] = "Использует интерполяцию ExponentialEaseOut для"
L["Uses a separate texture opacity below the HP threshold. The normal Opacity remains active above it."] = "Использует отдельную непрозрачность текстуры ниже порога здоровья. Выше порога действует обычная непрозрачность."
L["WARNING:\n\nAFK/DND status indicators do NOT update while you are inside an instance AND in combat.\nThis is a client/API limitation.\n\nOutside of instance combat they should work normally.\n\nEnable anyway?"] = "ВНИМАНИЕ:\n\nИндикаторы «Отошёл»/«Не беспокоить» НЕ обновляются, пока вы находитесь в подземелье И в бою.\nЭто ограничение клиента и API.\n\nВне боя в подземелье они работают нормально.\n\nВсё равно включить?"
L["WARNING: Best-guess tracking. Cooldowns are estimated; talents/resets may differ. If other party members use MSUF, kicks are synced via addon messages for better accuracy."] = "ВНИМАНИЕ: отслеживание приблизительное. Перезарядки оцениваются; таланты и сбросы могут отличаться. Если другие члены группы используют MSUF, прерывания синхронизируются через сообщения аддонов для большей точности."
L["Weapon enchant buffs (Windfury, Flametongue, Earthliving, etc.)."] = "Баффы наложения чар на оружие (ярость ветра, язык пламени, животворная земля и т. д.)."
L["What to export?"] = "Что экспортировать?"
L["When HP gradient is selected, choose the color used above the HP threshold. Single color uses this layer's tint and renders the source monochrome."] = "Когда выбран градиент здоровья, укажите цвет, используемый выше порога. «Один цвет» использует оттенок этого слоя и отображает источник монохромно."
L["When OFF: Bar snaps instantly to new values."] = "Если ВЫКЛ.: полоса мгновенно перескакивает на новые значения."
L["When OFF: Text updates are budget-gated"] = "Если ВЫКЛ.: обновления текста ограничены бюджетом"
L["When enabled, Blizzard handles countdown numbers natively in C++.\nDisables timer colors but eliminates all periodic timer CPU overhead.\nFont, size and position are still controlled by MSUF."] = "Когда включено, Blizzard обрабатывает числа обратного отсчёта нативно на C++.\nЦвета таймера при этом отключаются, зато исчезает вся периодическая нагрузка таймеров на ЦП.\nШрифт, размер и положение по-прежнему задаёт MSUF."
L["When enabled, aura cooldown text uses Safe / Warning / Urgent colors based on remaining time.\nWhen disabled, aura cooldown text always uses the Safe color."] = "Когда включено, текст перезарядки аур использует цвета «Безопасно» / «Предупреждение» / «Срочно» в зависимости от оставшегося времени.\nКогда выключено, всегда используется цвет «Безопасно»."
L["When enabled, placeholder auras can be shown while MSUF Edit Mode is active."] = "Когда включено, во время режима редактирования MSUF могут показываться ауры-заглушки."
L["When enabled, the cooldown swipe represents elapsed time (darkens as time is lost).\n\nTurn this OFF to keep the default cooldown-style swipe."] = "Когда включено, заливка перезарядки показывает прошедшее время (темнеет по мере его истечения).\n\nОтключите, чтобы сохранить стандартную заливку перезарядки."
L["When off, this unit uses Shared caps (Max Buffs/Debuffs, Icons per row). When on, it uses its own caps."] = "Когда выключено, этот юнит использует общие ограничения (макс. баффов/дебаффов, значков в ряду). Когда включено — собственные."
L["When off, this unit uses Shared filter settings. When on, it uses its own copy of the filters."] = "Когда выключено, этот юнит использует общие настройки фильтров. Когда включено — собственную копию фильтров."
L["When scope is set to 'Shared', settings apply globally. Select a unit and enable 'Override shared settings' to customize per unitframe."] = "Когда область действия — «Общие», настройки применяются глобально. Выберите юнита и включите «Переопределить общие настройки», чтобы настроить каждый фрейм отдельно."
L["When unchecked, this unit inherits Shared settings for text modes, absorb display, and spacers."] = "Если не отмечено, этот юнит наследует общие настройки текстовых режимов, отображения поглощения и разделителей."
L["When unchecked, this unit inherits Shared settings."] = "Если не отмечено, этот юнит наследует общие настройки."
L["Whirlwind (Fury)"] = "Вихрь (Неистовство)"
