L["Width:"] = "Ширина:"
L["Works only when the corresponding text mode is set to 'Full value + %' (or '% + Full value')."] = "Работает, только когда соответствующий текстовый режим — «Полное значение + %» (или «% + Полное значение»)."
L["for pixel-accurate text that matches the bar."] = "для текста с точностью до пикселя, совпадающего с полосой."
L["hp text"] = "текст здоровья"
