L["Open MSUF Edit Mode, select the frame, then drag it. Use the unit page > Anchor only for exact anchor/X/Y fine-tuning."] = "Открой режим редактирования MSUF и перетащи рамку. Для якоря и X/Y используй «Точка крепления» на странице персонажа."
L["Open that unit page and use Frame Basics for width, height, and scale. Text size is in Style > Fonts or the unit Text section."] = "На странице персонажа «Frame Basics» задаёт ширину, высоту и масштаб. Размер текста: «Style > Fonts» или «Text»."
L["Use the unit page for per-unit castbar toggles and Frames > Cast Bars for shared textures, direction, text, and interrupt options."] = "Параметры полосы для персонажа находятся на его странице. Общие настройки — в «Frames > Cast Bars»."
L["Boss frames normally appear only during boss encounters. Enable Boss Frames and use Edit Mode or Boss Preview to test them outside combat."] = "Рамки боссов появляются во время боёв. Включи Boss Frames и проверь их в режиме редактирования или предпросмотре."
L["Open Frames > Party/Raid Frames > Layout. Size & Scaling controls frame dimensions and scaling by group size. Group Layout controls growth, columns, and group visibility."] = "Открой «Frames > Party/Raid Frames > Layout». «Размер и масштаб» задаёт размеры рамок и масштаб в зависимости от размера группы. «Расположение группы» задаёт направление роста, столбцы и видимость групп."
L["Open the unit page and use Text for name/health/power text patterns, anchors, offsets, font sizes, and layering."] = "В «Text» на странице персонажа настрой имя, здоровье, ресурс, якоря, смещения, шрифт и слои."
L["Open Style > Colors. Bar Colors and Power Bar Colors control HP/power colors; Class Bar Colors controls class overrides."] = "Открой «Style > Colors». «Bar Colors» и «Power Bar Colors» задают здоровье и ресурс; «Class Bar Colors» — цвета классов."
L["Style > Fonts controls shared font settings. Unit pages contain per-unit name, health, and power text position and pattern settings."] = "«Style > Fonts» содержит общие настройки. Страницы персонажей задают положение и формат текста."
L["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Используй «Dashboard > Reset Positions» для перемещения рамок. Profiles нужен для сброса, копирования, импорта или замены профиля."
L["Open Profiles for active profile, spec auto-switching, 6.x import/export strings, and reset options."] = "Открой Profiles для активного профиля, смены специализации, импорта, экспорта и сброса."
L["Open Frames > Bars. Textures & Gradient controls shared bar textures; Frame Outline and Highlight Borders control borders."] = "Открой «Frames > Bars». «Textures & Gradient» задаёт текстуры; «Frame Outline» и «Highlight Borders» — границы."
L["Absorb styling and heal prediction are in Frames > Bars > Absorb Display. Use the Party or Raid scope there for group incoming heals."] = "Поглощение и прогноз лечения находятся в «Frames > Bars > Absorb Display». Выбери Party или Raid для лечения группы."
L["Open the matching unit page and check Frame Basics > Enable, Load Conditions, alpha/transparency, and range fade."] = "Проверь «Frame Basics > Enable», условия загрузки, прозрачность и исчезновение по дальности."
L["Open Frames > Party/Raid Frames > Layout. Check enable/show behavior, player/solo visibility, layout mode, frame scaling, and anchoring."] = "Открой «Frames > Party/Raid Frames > Layout». Проверь включение, видимость, схему, масштаб и якорь."
L["Open Frames > Party/Raid Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Открой «Frames > Party/Raid Frames > Status & Indicators» для значков, роли, лидера, помощника, готовности и фокуса."
L["Find settings and help"] = "Поиск настроек и справки"
L["Search enabled features in your own words."] = "Ищите включённые функции своими словами."
L["Search settings, then open a result to make your changes."] = "Найдите настройку и откройте результат, чтобы изменить её."
L["Try fewer words or a different spelling."] = "Попробуйте сократить запрос или изменить написание."
L["Best %d match(es). Open one to view its setting or help."] = "Лучшее совпадение: %d. Откройте его для просмотра настройки или справки."
L["Search or ask a question"] = "Поиск или вопрос"
L["Try \"raid auras\" or ask \"can you make my text bigger?\""] = "Попробуйте «ауры рейда» или спросите «как увеличить текст?»"
L["Start typing to search available settings and help."] = "Начните ввод для поиска настроек и справки."
L["Search settings..."] = "Поиск настроек..."
L["Search Examples"] = "Примеры запросов"
L["Post Priority Frames feature requests in MSUF Discord: https://discord.gg/2Gf9b2Wprz."] = "Публикуйте предложения по Priority Frames в MSUF Discord: https://discord.gg/2Gf9b2Wprz."

L["Matches appear while you type. Enter opens the selected result."] = "Результаты появляются при вводе. Enter открывает выбранный результат."

