L["The percentage applies in By group size mode. Exact raid dimensions below replace scaled width or height; 0 keeps the scaled base. Spacing and resource bar height still use the scaling percentage."] = "Процент применяется в режиме «По размеру группы». Точные размеры рейда ниже заменяют масштабированную ширину или высоту; 0 сохраняет масштабированную основу. Интервалы и высота полосы ресурса по-прежнему используют процент масштаба."
