L["Group visibility options apply only to their matching Party, Raid, or Mythic Raid scope. Empty groups collapse when Preserve raid groups is enabled."] = "Параметры видимости действуют только для соответствующего режима: группа, рейд или эпохальный рейд. Пустые группы сворачиваются, если включено сохранение рейдовых групп."

