L["Each icon marks a buff that a class in your group can cast but this member lacks. Thorns is checked on members with the Tank role (on everyone with Thorns only on tanks off), Arcane Intellect and Divine Spirit on mana users. Combat, encounters and PvP matches hide aura data, so the icons keep their last known state until it ends."] = "Каждый значок обозначает эффект, который может наложить класс из вашей группы, но которого нет у этого участника. Шипы проверяются у участников с ролью танка (у всех, если «Шипы только для танков» выключено), Чародейский интеллект и Божественный дух — у пользователей маны. В бою, во время схваток с боссами и PvP-матчей данные аур скрыты, поэтому значки сохраняют последнее известное состояние до их окончания."

