L["You cannot delete the 'Default' profile. Use Reset instead."] = "Профиль «Default» нельзя удалить. Используйте сброс."
L["Cannot delete the last remaining profile."] = "Нельзя удалить последний оставшийся профиль."
L["Profile '%s' deleted."] = "Профиль «%s» удалён."
L["No source profile specified."] = "Не указан исходный профиль."
