L["Import warning: missing texture '%s' in %s. Using fallback texture."] = "Предупреждение импорта: текстура «%s» отсутствует в %s. Используется запасная текстура."
L["Import warning: %d more missing media item(s)."] = "Предупреждение импорта: ещё отсутствующих медиафайлов: %d."
L["Imported %s settings into the active profile."] = "Настройки %s импортированы в активный профиль."
