L["%s section"] = "раздел %s"
L["Abbreviates large HP numbers, absorb included, instead of printing the full value. Available while a slot shows a number."] = "сокращает большие числа HP, включая поглощение, вместо вывода полного значения. Доступно, пока в слоте отображается число."
L["Action failed"] = "Действие не выполнено"
L["Add Custom Buff"] = "добавлен пользовательский усиление."
L["Adds a shade over the filled part of health bars that darkens toward the arrows you pick. The strength slider sets how dark it gets."] = "добавляет оттенок к закрашенной части полосы здоровья, который затемняется по направлению к выбранным стрелкам. Ползунок интенсивности определяет, насколько темно будет."
L["Adds a shield glow at the end of the health bar when absorbs plus incoming heals cover all of the missing health."] = "добавляет свечение щита в конце полоса здоровья, когда поглощается, а входящие исцеления покрывают все недостающие здоровье."
L["Adds or removes a fade direction; the shade darkens toward this arrow. Directions can be combined, and one always stays on."] = "добавляет или удаляет направление затухания; тень темнеет по направлению к этой стрелке. Направления можно комбинировать, и всегда остается одно."
L["Adds the same fading shade to power bars, with its own direction arrows and strength."] = "добавляет тот же оттенок выцветания, что и полосы ресурса, но со своими стрелками направления и силой."
L["Adds the unit's absorb shield amount after this slot's HP value, with or without a shield icon. Shown only while a shield is active."] = "добавляет количество поглощающего щита отряда после значения HP этого слота, со значком щита или без него. Отображается только тогда, когда активен щит."
L["Also keeps Blizzard Focus visible; /reload required."] = "также сохраняет фокус Blizzard видимым; Требуется /reload."
L["Also keeps Blizzard Target visible; /reload required."] = "также сохраняет цель Blizzard видимой; Требуется /reload."
L["Aura Options, Ordering and Aura Style belong to this UnitFrame. Global icon appearance: %s."] = "Опции Aura, порядок и Aura Style принадлежат этому рамка юнита. Общий внешний вид значка: %s."
L["Aura sensor enabled for Dispel. Buff and Debuff icon caps may stay at 0."] = "датчик ауры включен для рассеивания. Бафф и Дебафф ограничения количества значков могут оставаться на уровне 0."
L["Aura tooltip caster names"] = "имена заклинателей во всплывающей подсказке ауры."
L["Aura type:"] = "Тип ауры:"
L["Automatic keeps each resource's established text, such as Current for Combo Points and Current / Maximum for Vengeance Soul Fragments. The explicit modes override only the central resource value; Rune timers, Ebon Might duration and the Ironfur stack counter keep their native formats."] = "автоматически сохраняет установленный текст каждого ресурса, например «Текущий» для очки серии приёмов и «Текущий/Максимальный» для фрагменты души «Месть». Явные режимы переопределяют только значение центрального ресурса; Таймеры рун, продолжительность Ebon Might и счетчик стека Ironfur сохраняют свои собственные форматы."
