L["Custom: %s"] = "Пользовательский: %s"
L["Cut direction"] = "Направление резания"
L["Cuts long spell names on every castbar to Max name length and marks the cut with '...'. Reserved space applies only while this is on."] = "обрезает длинный названия заклинаний на каждом полоса заклинания до максимальной длины имени и помечает обрезку знаком «...». Зарезервированное пространство применяется только тогда, когда оно включено."
L["Daylight"] = "Дневной свет"
L["Decimals below sec"] = "десятичные знаки ниже секунды."
L["Deletes all MSUF profiles and settings after confirmation. Suite profiles are kept."] = "удаляет все профили и настройки MSUF после подтверждения. Профили Suite сохраняются."
L["Deletes all Suite profiles and skin settings after confirmation. MSUF data stays intact."] = "удаляет все профили Suite и настройки скинов после подтверждения. Данные MSUF остаются нетронутыми."
L["Dispel Border, Overlay, and Symbol need each UnitFrame's Aura sensor. Enable Buffs or Debuffs on the affected UnitFrame, or turn on its Dispel feature to enable the sensor automatically. Both icon caps may stay at 0."] = "для Dispel граница, Overlay и символа требуется датчик ауры каждого рамка юнита. Включите усиление или ослабление на затронутом рамка юнита или включите его функцию рассеивания, чтобы датчик автоматически включался. Оба ограничения количества значков могут оставаться на уровне 0."
L["Dispel Border, Overlay, and Symbol need this UnitFrame's Aura sensor. Enable Buffs or Debuffs, or turn on this Dispel feature to enable the sensor automatically. Set both icon caps to 0 if you want no aura icons."] = "Dispel граница, Overlay и Символ требуют датчика ауры этого рамка юнита. Включите усиление или ослабление или включите функцию рассеивания, чтобы датчик автоматически включался. Установите для обоих ограничения количества значков значение 0, если вы не хотите, чтобы значки ауры исчезли."
L["Dots on Target"] = "Точки на цели"
L["Drain"] = "Убывание"
L["Draw order on the shared 0-30 layer scale. Raise it to draw the outline above text, icons or auras on a lower layer."] = "порядок отрисовки по общей шкале слой от 0 до 30. Поднимите его, чтобы нарисовать контур над текстом, значками или аурами на нижнем слой."
L["Draws absorb shields on the unit, such as Power Word: Shield, as an overlay on the health bar."] = "Draw поглощает щиты на юнит, например Слово силы: Щит, в качестве наложения на полоса здоровья."
L["Each castbar text can override the shared castbar text color. Target text exists on Target, Focus, Boss, and Arena."] = "каждый текст полоса заклинания может переопределять общий цвет текста полоса заклинания. Текст цели существует на Target, Focus, босс и Arena."
L["Each text has three slots: left, center and right. The slot picked here is the one the value, Hide % sign and slot size settings edit."] = "Каждый текст имеет три слота: левый, центральный и правый. Здесь выбран слот, соответствующий значению. Скройте % sign и отредактируйте настройки размера слота."
L["Edge softness"] = "Мягкость кромок."
L["Effect Layer (0-30)"] = "Эффект слой (0-30)"
L["Ember"] = "Эмбер"
L["Enable Swing Timer module"] = "включить модуль таймера поворота."
L["Enable the module, then drag the selected bars outside combat. Main Hand and Off Hand can be shown together. Positions are saved in this MSUF profile."] = "включите модуль, затем перетащите выбранные полосы за пределы боя. Основная рука и вторая рука могут отображаться вместе. Позиции сохраняются в этом профиле MSUF."
L["Factory reset MSUF Suite?\n\nAll Suite profiles and skin settings on this account will be deleted. MSUF settings stay intact. The UI will reload."] = "Сброс к заводским настройкам. MSUF Suite?\n\nВсе профили Suite и настройки скинов в этой учетной записи будут удалены. Настройки MSUF остаются неизменными. Пользовательский интерфейс перезагрузится."
L["Factory reset MSUF?\n\nAll MSUF profiles and settings on this account will be deleted. Suite profiles are kept, but the active Suite profile may follow MSUF back to Default. The UI will reload."] = "Сброс к заводским настройкам MSUF?\n\nВсе профили и настройки MSUF в этой учетной записи будут удалены. Профили Suite сохраняются, но активный профиль Suite может следовать за MSUF обратно к значению по умолчанию. Пользовательский интерфейс перезагрузится."
L["Fill and color mode affect only the health background; foreground health coloring stays independent."] = "режим заливки и цвета влияет только на фон здоровье; Цвет переднего плана здоровье остается независимым."
L["Fill direction"] = "Направление заполнения"
L["Fill up"] = "Заполнить"
L["Fix positions, print help, or reset MSUF or Suite."] = "исправить положение, распечатать справку или сбросить MSUF или Suite."
L["Flips the fill direction on the Target castbar only, so it can mirror your Player castbar when the two frames face each other."] = "меняет направление заполнения только на Target полоса заклинания, поэтому оно может отражать вашего Player полоса заклинания, когда два рамки обращены друг к другу."
L["Focus color is in %s."] = "Цвет фокуса — %s."
L["Focus interrupt tracker"] = "отслеживание прерываний фокусировки."
L["Font"] = "Шрифт"
L["Font outline"] = "Шрифт контур"
L["Font size of the slot picked in Text slots only. Slots you never resize keep the normal text size."] = "размер шрифта слота, выбранного только в текстовых слотах. Слоты, размер которых никогда не изменяется, сохраняют нормальный размер текста."
L["Frame Outline Color"] = "рамка контур Цвет"
L["Gives this scope its own text style, colors and name shortening, so Shared changes stop reaching it. The font family always stays shared."] = "придает этому область настроек собственный стиль текста, цвета и сокращение имени, поэтому общие изменения не доходят до него. Семейство шрифтов всегда остается общим."
L["Gives this unit or group its own gradient, absorb, outline and highlight settings instead of following Shared. Turning it off keeps your custom values."] = "дает этому устройству или группе собственные настройки градиента, поглощения, контур и выделения вместо использования общих настроек. При его отключении ваши пользовательские значения сохраняются."
L["Gradually brightens the bar toward white as a cast nears its end, so the last moment of a cast is easy to spot."] = "Постепенно полоса становится светлее в сторону белого по мере того, как заклинание приближается к концу, поэтому последний момент заклинание легко заметить."
L["Grid %s/%s"] = "Сетка %s/%s"
L["Group frame provider"] = "поставщик группы рамка"
L["Group threat visuals show for"] = "визуальные эффекты групповой угрозы"
L["Grow"] = "Расти"
L["HP value"] = "значение HP"
L["Heal-Absorb / Negative Heal"] = "Исцеление-Поглощение / Негативное исцеление"
L["Health gradient stops"] = "здоровье ограничители градиента"
L["Hide in Housing"] = "Спрятаться в жильё."
L["Higher numbers draw this text in front. Portrait, aura and status icon layers use the same 0-30 scale; set it above whatever covers the text."] = "при более высоких цифрах этот текст будет отображаться спереди. Слои портрета, ауры и значков статуса используют одну и ту же шкалу от 0 до 30; установите его выше всего, что покрывает текст."
L["Highlight Priority Order"] = "порядок выделения приоритета"
L["Highlights the Boss frame of the boss you are targeting. It is shared by all boss frames, so it changes only on the Shared scope."] = "выделяет босс рамка босс, на который вы нацелены. Он общий для всех босс рамки, поэтому меняется только на Shared область настроек."
L["How dark the health bar shade gets at its strongest edge. 0 shows no shade, 1 uses the full shade color."] = "Насколько темным становится оттенок полоса здоровья на самом сильном крае. 0 показывает отсутствие оттенка, 1 использует полный оттенок."
L["How dark the power bar shade gets at its strongest edge. 0 shows no shade, 1 uses the full shade color."] = "Насколько темным становится оттенок полоса ресурса на самом сильном крае. 0 показывает отсутствие оттенка, 1 использует полный оттенок."
L["How far the bar jolts, in pixels. 0 turns the shake off even while Shake on interrupt is enabled."] = "Насколько сильно трясется полоса, в пикселях. Значение 0 отключает встряхивание, даже если включено прерывание «Встряхивание при включении»."
L["How long an interrupted cast stays visible with the interrupt message before the bar hides. 0 hides it immediately."] = "Как долго прерванный заклинание остается видимым с сообщением о прерывании, прежде чем полоса скроется. 0 скрывает это немедленно."
L["How long the text takes to fully appear once your mouse enters the unit frame. 0 shows it instantly."] = "сколько времени потребуется, чтобы текст полностью появился после того, как мышь войдет в рамка юнита. 0 показывает это мгновенно."
L["How long the text takes to fully fade away after your mouse leaves the unit frame. 0 hides it instantly."] = "сколько времени понадобится тексту, чтобы полностью исчезнуть после того, как мышь покинет рамка юнита. 0 мгновенно скрывает это."
L["Hunted Foe"] = "Загнанный враг"
L["Icon (follows castbar)"] = "значок (следует за полоса заклинания)"
L["Icon Border"] = "Значок граница"
L["Icon Effect"] = "Эффект значка"
L["Icon Shadow"] = "Тень значка"
L["Includes each frame's own settings, auras and castbar. Shared appearance settings stay unchanged."] = "включает собственные настройки, ауры и полоса заклинания каждого рамка. Общие настройки внешнего вида остаются неизменными."
L["Independent from MSUF Enable; /reload required."] = "Независимо от MSUF Включить; Требуется /reload."
L["Jade"] = "Джейд"
L["Jolts a castbar sideways when the cast it shows is interrupted, so kicks are easy to notice. Applies to every castbar."] = "трясет полоса заклинания в сторону, когда показанный им заклинание прерывается, поэтому удары ногами легко заметить. Применяется к каждому полоса заклинания."
L["Keeps this many extra pixels free next to the spell name, on top of the room kept for the cast time, so long names stay clear of the timer."] = "оставляет свободными дополнительные пиксели рядом с название заклинания, поверх комнаты, отведенной для времени заклинание, поэтому длинные имена остаются вне таймера."
L["Keeps this text hidden until your mouse is over the unit frame. Name, HP and power text each have their own switch."] = "этот текст остается скрытым, пока указатель мыши не окажется над рамка юнита. Имя, HP и текст ресурс имеют собственный переключатель."
L["Large Groups"] = "Большие группы"
L["Left edge: lower corner"] = "Левый край: нижний угол."
L["Left edge: upper corner"] = "Левый край: верхний угол."
L["Lets the spark stick out above and below the bar at about twice its height. Only matters while the spark is shown."] = "позволяет искре выступать выше и ниже полоса примерно на удвоенную высоту. Имеет значение только тогда, когда есть искра."
L["Lower %s"] = "Понизить приоритет %s"
L["MSUF (Forever Version)"] = "MSUF (вечная версия)"
L["MSUF Factory Reset"] = "MSUF Возврат к заводским настройкам"
L["Main Hand"] = "Основная рука"
L["Makes channeled spells fill up like normal casts. Off keeps the classic look where a channel starts full and drains."] = "Заставляет направленный заклинания заполняться, как при обычном применении. В выключенном состоянии сохраняется классический стиль, когда канал сначала заполняется, а затем опустошается."
L["Manual width for the detached Player power bar. Available while Width mode is Manual; dragging it releases Sync width to Class Resource, because that sync would otherwise win. Unset, the bar inherits the Player frame width."] = "Ручная ширина для отдельного ресурс игрока полоса. Доступно, если режим ширины установлен вручную; его перетаскивание освобождает ширину синхронизации до ресурс класса, потому что в противном случае эта синхронизация выиграла бы. Если не задано, полоса наследует ширину Player рамка."
L["Mapkotwo"] = "Мапкотво"
L["Marked Add"] = "отмечено добавление"
L["Maximum Health Loss Color"] = "Максимальный цвет потери здоровье"
L["Menu appearance preset"] = "предустановка внешнего вида меню."
L["Mid"] = "Средний"
L["Mirrors the HP text: left and right slots swap sides and multi-value choices flip, so Current / Percent becomes Percent / Current."] = "Отражает текст HP: левый и правый слоты меняются местами, а варианты с несколькими значениями переворачиваются, поэтому Текущий / Процент становится Процентом / Текущим."
L["Modifier key"] = "клавиша-модификатор"
L["Moonlit Tank"] = "Лунный свет танк"
L["Move the group or selected slot directly in Preview."] = "переместите группу или выбранный слот непосредственно в окне предварительного просмотра."
L["Move the name directly in Preview."] = "переместите имя прямо в предварительный просмотр."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width. In Automatic mode, Augmentation Evoker uses this bar for Ebon Might; an explicit Mana selection keeps it as Mana."] = "перемещает ресурс игрока полоса из рамка юнита. Anchor соединяет его со стеком ресурсов класса; Синхронизация соответствует только ширине стека. В автоматическом режиме пробудитель «Усиление» использует этот полоса для Ebon Might; явный выбор маны сохраняет ее как ману."
L["Mythic"] = "Эпохальный"
L["Mythic Raid frames"] = "Мифический рейд рамки"
L["Non-tanks"] = "игроки не в роли танка"
L["Number only"] = "только номер"
L["Off (default): panels keep the Classic Glass appearance. On: panels and navigation follow your accent color. Success, warning and danger colors never change."] = "Выкл. (по умолчанию): панели сохраняют внешний вид Classic Glass. Вкл.: панели и навигация соответствуют вашему акцентному цвету. Цвета успеха, предупреждения и опасности никогда не меняются."
L["Off (default): the accent colors buttons, tabs and highlights while panels keep the selected look. On: panels, borders and the navigation rail follow the accent too. Success, warning and danger colors never change."] = "Выкл. (по умолчанию): кнопки, вкладки и выделение выделены цветом акцентов, а на панелях сохраняется выбранный стиль. Включено: панели, границы и навигационная полоса также следуют за акцентом. Цвета успеха, предупреждения и опасности никогда не меняются."
L["Off Hand"] = "Левая рука"
L["Offline %s s"] = "Не в сети %s с"
L["On: aura tooltips name who applied the aura, coloured by reaction or class, through the game's own 12.1.5 option, and MSUF re-enables it after every login. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "Включено: во всплывающих подсказках ауры указывается имя того, кто применил ауру, окрашенную в зависимости от реакции или класса, с помощью собственной опции игры 12.1.5, и MSUF повторно включает ее после каждого входа в систему. Выкл. (по умолчанию): MSUF никогда не затрагивает параметры игры, поэтому другие дополнения или ручные настройки консоли сохраняют контроль; выключение этого переключателя очищает опцию один раз."
L["On: dragging this text in Preview moves all its slots together. Off: each visible slot gets its own handle so you can place it separately."] = "Вкл.: при перетаскивании этого текста в режиме предварительного просмотра все его слоты перемещаются вместе. Выкл.: каждый видимый слот имеет собственный дескриптор, поэтому его можно разместить отдельно."
L["Opacity %"] = "Непрозрачность %"
L["Open Priority Frames for %s"] = "Открытый приоритет рамки для %s"
L["Open Suite Modules"] = "Модули открытого пакета"
L["Open a Frame"] = "Откройте рамка."
L["Open search result %s"] = "Открыть результат поиска %s"
L["Opens the global Aura icon appearance: shape, border, shadow, colors and native Player weapon enchants. This frame's container Style stays here."] = "открывает глобальный внешний вид значка Ауры: форму, граница, тень, цвета и собственные чары оружия игрока. Стиль контейнера рамка остается здесь."
L["Optional modules beyond unit frames: action bars, bags, chat, minimap and more."] = "дополнительные модули помимо рамки юнитов: панели действий, сумки, чат, мини-карта и многое другое."
L["Ordering and individual Style are edited here. Global icon theme: %s."] = "Здесь редактируются порядок и индивидуальный стиль. Глобальная тема значков: %s."
L["Orders Class Resource numeric text, Rune times and the Ebon Might duration text independently from the Class Resource bar and Player Power text."] = "устанавливает порядок отрисовки числового текста ресурс класса, времени рун и текста продолжительности Ebon Might независимо от текста ресурс класса полоса и ресурс игрока."
L["Orders only the normal Player Power bar. It does not control Class Resource pips or their text."] = "устанавливает порядок отрисовки только обычного ресурс игрока полоса. Он не управляет пунктами ресурс класса или их текстом."
L["Orders only the normal Player Power text. The visible Essence count and Ebon Might time belong to Class Resource text."] = "устанавливает порядок отрисовки только обычного текста ресурс игрока. Видимое количество эссенций и время Ebon Might принадлежат тексту ресурс класса."
L["Orders the Class Resource bar and pips. Its numeric, Rune and Ebon duration text uses the separate Class Resource text layer under Appearance > Text."] = "устанавливает порядок рисования ресурс класса полоса и пунктов. Для его числового, рунического и черного текста продолжительности используется отдельный текст ресурс класса слой в разделе «Внешний вид» > «Текст»."
