L["Round MSUF castbar surfaces and outlines. Blizzard castbars, spell icons, and the GCD bar are not changed."] = "Круглые поверхности и контуры MSUF полоса заклинания. Значки Blizzard полосы заклинаний, заклинание и НОД полоса не изменяются."
L["Round level badge"] = "Круглый значок уровня."
L["Round rectangular class resource bars. Circle, Diamond, and Hex shapes are unchanged."] = "Круглые прямоугольные стержни ресурс класса. Формы круга, ромба и шестигранника не изменились."
L["Scale %"] = "Масштаб %"
L["Search for %s"] = "Искать %s"
