L["Selects which side and corner of slanted Health and Power bars is cut."] = "выбирает, какая сторона и угол наклонных здоровье и полосы ресурса обрезаются."
L["Shades the end of the Player castbar by your latency or spell queue window, whichever is larger, to help time your next spell. Player castbar only."] = "затеняет конец проигрывателя полоса заклинания в соответствии с вашей задержкой или окном очереди заклинание, в зависимости от того, что больше, чтобы помочь рассчитать время для следующего заклинание. Только плеер полоса заклинания."
L["Shadow Alpha (%)"] = "Тень Альфа (%)"
L["Shadow Size"] = "Размер тени"
L["Shadow distance"] = "Расстояние тени"
L["Shape, border and shadow: %s. All controls here remain Group-scope aware."] = "Форма, граница и тень: %s. Все элементы управления здесь остаются в курсе Group-область настроек."
L["Sharp / Pixel"] = "Резкий/Пиксельный"
L["Show Duration Bar"] = "Продолжительность показа полоса"
L["Show MSUF button in game menu"] = "показывать кнопку MSUF в меню игры."
L["Show Timer Text"] = "Показать текст таймера"
L["Show Tooltip"] = "Показать подсказку"
L["Show Weapon Enchants on Player"] = "показывать чары оружия на игроке."
L["Show bar title"] = "Показать заголовок полоса."
L["Show castbar with Focus Kick icon"] = "показать полоса заклинания со значком Focus Kick."
L["Show caster names in aura tooltips"] = "отображать имена заклинателей во всплывающих подсказках аур."
L["Show on Arena castbars"] = "Выступление на арене полосы заклинаний"
L["Show preview drag hint animation"] = "показывать анимацию подсказки для предварительного просмотра."
L["Show remaining time"] = "Показать оставшееся время."
L["Show this frame only when its unit is below full health. At full health it is transparent, even in combat or with a target. Replaces the Out of combat, No target, and Out of combat and no target rules; other hide conditions still apply. Edit Mode keeps the frame visible for editing. The transparent frame can still receive mouse clicks."] = "показывать этот рамка только тогда, когда его единица измерения ниже полного здоровье. У полного здоровье он прозрачен, даже в бою или с мишенью. Заменяет правила «Вне боя», «Нет цели» и «Вне боя и нет цели»; другие условия сокрытия все еще применяются. В режиме редактирования рамка остается видимым для редактирования. Прозрачный рамка по-прежнему может воспринимать щелчки мыши."
L["Show unitframe tooltips"] = "Показать всплывающие подсказки рамка юнита."
L["Shows HP percent with one decimal (for example, 63.4 instead of 63) in every HP slot that shows a percent."] = "Показывает процент HP с одним десятичным числом (например, 63,4 вместо 63) в каждом слоте HP, где отображается процент."
L["Shows a shield glow at the end of the health bar while the unit is at full health and still has an absorb shield."] = "показывает свечение щита в конце полоса здоровья, когда отряд полностью заполнен здоровье и все еще имеет поглощающий щит."
L["Shows heal absorbs, effects that soak up incoming healing before health can rise, as a bar over current health."] = "показывает поглощение исцеления, эффекты, которые поглощают входящее исцеление до того, как здоровье сможет подняться, поскольку полоса превосходит текущий здоровье."
L["Shows incoming heals as a bar on the health bar before they land. Only your own heals count unless Include healing from others is on."] = "отображает входящие исцеления как полоса на полоса здоровья перед тем, как они приземлятся. Учитываются только ваши собственные исцеления, если не включена опция «Включить лечение от других»."
L["Shows sample bars on the frames of the selected scope, even while this bar is turned off, so you can check its look. Cannot be turned on in combat."] = "показывает панели сэмплов на рамки выбранного область настроек, даже если этот полоса выключен, поэтому вы можете проверить его стиль. Невозможно включить в бою."
L["Shows the aggro color on the border when the unit has threat: your frame while you hold aggro, enemies attacking you, and group members with high threat."] = "показывает цвет агро на граница, когда юнит имеет угрозу: ваш рамка, когда вы удерживаете агро, враги, атакующие вас, и члены группы с высокой угрозой."
L["Shows the percent as a bare number (63 instead of 63%) in the selected slot only. Available when that slot's value includes a percent."] = "показывает проценты в виде простого числа (63 вместо 63%) только в выбранном слоте. Доступно, если значение этого слота включает проценты."
L["Shows the remaining global cooldown in the Player castbar time text while the GCD bar runs."] = "показывает оставшийся глобальный время восстановления в тексте времени проигрывателя полоса заклинания во время работы GCD полоса."
L["Shows the selected cut on a Health and Power bar sample."] = "показывает выбранный разрез на образце здоровье и полоса ресурса."
L["Slanted"] = "наклонный"
L["Slanted bar preview"] = "Предварительный просмотр наклонного полоса"
L["Slug"] = "Slug"
L["Smooth"] = "Гладкий"
L["Soft gradient gives the whole frame a clear, portrait-safe hover cue. Solid border keeps a crisp edge. Choose its color in %s."] = "Мягкий градиент придает всему рамка четкий, безопасный для портретной ориентации сигнал при наведении. Твердый граница сохраняет четкие края. Выберите его цвет в %s."
L["Some settings in this section differ from their defaults. Reset section restores them."] = "Некоторые настройки в этом разделе отличаются от значений по умолчанию. Раздел Reset восстанавливает их."
L["Spell ID %s"] = "заклинание Идентификатор %s"
L["Spell Indicator Order"] = "Ордер индикатора заклинание"
L["Spell names longer than this many characters are cut and end in '...'. Names are also trimmed to fit the free bar width, so narrow bars may show fewer."] = "названия заклинаний длиннее указанного количества символов обрезается и заканчивается на '...'. Имена также обрезаются, чтобы соответствовать свободной ширине полоса, поэтому узкие полосы могут отображаться меньше."
L["Spent power drops at once while the spent part briefly stays highlighted, then fades; turns off Smooth power bar. Set per unit, like Smooth power bar."] = "израсходованный ресурс выпадает сразу, при этом потраченная часть кратковременно остается подсвеченной, а затем исчезает; выключает Smooth полоса ресурса. Устанавливается на единицу, например Smooth полоса ресурса."
