L["Symbol anchor"] = "привязка символа"
L["Symbol opacity"] = "непрозрачность символа"
L["Symbol placed between values that share one slot, like Current and Percent. Used by all slots of this text."] = "символ, размещаемый между значениями, которые используют один слот, например ток и процент. Используется всеми слотами этого текста."
