L["The typeface for all unit and group frame text; every scope shares it. Fonts other addons register through SharedMedia also appear here."] = "шрифт для всего текста отряда и группы рамка; каждый область настроек разделяет его. Здесь также отображаются шрифты других аддонов, зарегистрированных через SharedMedia."
