L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in %s, scoped by Aura type."] = "цвета таймера и рассеивания используются в аурах живого объекта /group и в каждом предварительном просмотре. Значок граница и цвета теней находятся в %s, ограниченном типом Aura."
L["Timer font"] = "шрифт таймера."
L["Timer progression"] = "прогресс таймера"
