L["Tracked spell %s"] = "Отслеживаемое заклинание: %s"
L["Tracked spell tile %d"] = "Ячейка отслеживаемого заклинания %d"
L["Turns every HP text slot on this frame on or off. The health bar is not affected, and your slot setup is kept."] = "включает или выключает каждый текстовый слот HP на этом рамка. На полоса здоровья это не влияет, и настройки слота сохраняются."
L["Turns every power text slot on this frame on or off. The power bar is not affected, and your slot setup is kept."] = "включает или выключает каждый текстовый слот ресурс на этом рамка. На полоса ресурса это не влияет, и настройки слота сохраняются."
L["Turns off custom font settings on every unit and group scope at once, so they all follow Shared again."] = "отключает пользовательские настройки шрифта для каждого устройства и группы область настроек одновременно, поэтому все они снова следуют за общим."
L["Turns off custom settings on every unit and group scope at once, so all frames follow Shared again. Their custom values stay saved."] = "отключает пользовательские настройки для каждого устройства и группы область настроек одновременно, поэтому все рамки снова следуют за общими. Их пользовательские значения остаются сохраненными."
L["Turns this frame's name text on or off. Its anchor, size and color stay saved while it is off."] = "Включает или выключает текст имени этого рамка. Его якорь, размер и цвет сохраняются, пока он выключен."
L["Unavailable fill color"] = "недоступен цвет заливки."
L["Updates the Player power text on every power tick instead of the regular update rate. Only the Player frame uses it; set it on the Shared scope."] = "обновляет текст ресурс игрока при каждом тике ресурс вместо обычной частоты обновления. Его использует только Player рамка; установите его на общий область настроек."
L["Use MapkoSkin for MSUF menus"] = "используйте MapkoSkin для меню MSUF."
L["Use NSRT nicknames on MSUF frames"] = "используйте псевдонимы NSRT на MSUF рамки."
L["Use Preview and drag Swing Timers to see textures without attacking."] = "используйте предварительный просмотр и перетаскивайте таймеры поворота, чтобы видеть текстуры, не атакуя."
L["Use bar background texture"] = "использовать фоновую текстуру полоса."
L["Use bar texture"] = "использовать текстуру полоса."
L["Violet"] = "Фиолетовый"
L["Voidcaller"] = "Призыватель Бездны"
L["What the selected slot shows. None leaves the slot empty; choices with several values are joined by the Delimiter."] = "Что показывает выбранный слот. None оставляет слот пустым; варианты с несколькими значениями объединяются разделителем."
L["When anchored here, Player power settings are managed by Class Resources. In Automatic mode, Augmentation Evoker shows Ebon Might on this bar."] = "При закреплении здесь параметры ресурс игрока управляются ресурсами класса. В автоматическом режиме пробудитель «Усиление» отображает Ebon Might на этом полоса."
L["When several highlight borders show at once, the highest one in the list wins. Turn this on to reorder the list by dragging."] = "Когда одновременно отображается несколько границ выделения, побеждает самая высокая в списке. Включите эту опцию, чтобы изменить порядок списка путем перетаскивания."
L["Where the name is pinned on the frame and how it aligns. Dragging it in Preview offsets it from this point."] = "Где закреплено имя на рамка и как оно совмещается. Перетаскивание его в режиме предварительного просмотра смещает его от этой точки."
L["Which way the bar grows during a cast, on every castbar. Channels drain the other way unless Always use fill direction for all casts is on."] = "Каким образом полоса растет во время заклинание, на каждом полоса заклинания. Каналы сливаются в другую сторону, если не включен параметр Всегда использовать направление заполнения для всех приведения."
L["Width in pixels of the normal frame outline; 0 hides it. Aggro, dispel and other highlight borders use their own thickness."] = "Ширина в пикселях обычного рамка контур; 0 скрывает это. Границы агро, рассеивания и других ярких эффектов имеют собственную толщину."
L["Width of the border around each castbar, in pixels; 0 removes it. The Interrupt Ready border style colors this border, so keep it above 0 for that style."] = "ширина граница вокруг каждого полоса заклинания в пикселях; 0 удаляет его. Стиль граница, готовый к прерыванию, окрашивает этот граница, поэтому для этого стиля оставьте значение выше 0."
L["Window %d"] = "Окно %d"
L["Writes the instant spell's name on the GCD bar and shows its icon. Off leaves the spell text blank."] = "записывает мгновенное имя заклинание на GCD полоса и показывает его значок. Выкл. оставляет текст заклинание пустым."
